/** All translations for zizhitongjian ch.167 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "資治通鑑 第167卷卷第一百六十七", literal: "Comprehensive Mirror in Aid of Governance, Volume 167, Roll 167", idiomatic: "Comprehensive Mirror in Aid of Governance, Volume 167" },
  { zh: "【陳紀一】　起強圉赤奮若，盡屠維單閼，凡三年。", literal: "[Chen Records 1] From Qiangyu Chifenruo through Tuyi Danqian; three years in all.", idiomatic: "[Chen Records 1] From Qiangyu Chifenruo through Tuyi Danqian—three years in all." },
  { zh: "春，正月，辛丑，周公即天王位，柴燎告天，朝百官於露門；", literal: "In spring, the first month, on xinchou, the Duke of Zhou took the Heavenly Kingship, kindled firewood and reported to Heaven, and held court for the hundred officials at Lumen Gate;", idiomatic: "In spring, the first month, on xinchou, Duke of Zhou Yuwen Jue took the Heavenly Kingship, kindled the sacred fire and reported to Heaven, and held court for the hundred officials at Lumen Gate;" },
  { zh: "追尊王考文公為文王，妣為文後；", literal: "he posthumously honored his deceased father Duke Wen as King Wen and his mother as Queen Wen;", idiomatic: "he posthumously honored his deceased father Duke Wen as King Wen and his mother as Queen Wen;" },
  { zh: "大赦。", literal: "a general amnesty was proclaimed.", idiomatic: "and proclaimed a general amnesty." },
  { zh: "封魏恭帝為宋公。", literal: "The Wei Emperor Gong was enfeoffed as Duke of Song.", idiomatic: "The Wei Emperor Gong was enfeoffed as Duke of Song." },
  { zh: "以木德承魏水，行夏之時，服色尚黑。", literal: "With the virtue of Wood succeeding Wei's Water, they followed Xia's calendar and favored black in dress and color.", idiomatic: "Proclaiming the virtue of Wood to succeed Wei's Water, they followed the Xia calendar and favored black in dress and regalia." },
  { zh: "以李弼為太師，趙貴為太傅、大塚宰，獨孤信為太保、大宗伯，中山公護為大司馬。", literal: "Li Bi was made Grand Preceptor, Zhao Gui Grand Tutor and Grand Chief Minister, Dugu Xin Grand Guardian and Grand Director of the Masses, and Duke Hu of Zhongshan Grand Marshal.", idiomatic: "Li Bi was made grand preceptor, Zhao Gui grand tutor and grand chief minister, Dugu Xin grand guardian and grand director of the masses, and Duke Hu of Zhongshan grand marshal." },
  { zh: "詔以王琳為司空、驃騎大將軍，以尚書右僕射王通為左僕射。", literal: "An edict made Wang Lin Minister of Works and General of Agile Cavalry, and Right Vice Director of the Masters of Writing Wang Tong Left Vice Director.", idiomatic: "An edict made Wang Lin minister of works and general of agile cavalry, and made right vice director Wang Tong left vice director." },
  { zh: "周王祀圜丘，自謂先世出於神農，以神農配二丘，始祖獻侯配南北郊，文王配明堂，廟號太祖。", literal: "The Zhou king sacrificed at the Round Mound; he held that his forebears came from Shennong; Shennong was paired at the two mounds, the founding ancestor Duke Xian at the southern and northern suburbs, King Wen at the Bright Hall, and his temple name was Taizu.", idiomatic: "The Northern Zhou king sacrificed at the Round Mound; he held that his line descended from Shennong; Shennong was paired at the two mounds, the founding ancestor Duke Xian at the southern and northern suburbs, King Wen at the Bright Hall, and his temple name was Taizu." },
  { zh: "癸卯，祀方丘。", literal: "On guimao, he sacrificed at the Square Mound.", idiomatic: "On guimao, he sacrificed at the Square Mound." },
  { zh: "甲辰，祭大社。", literal: "On jiachen, he sacrificed to the Great Altar of Soil and Grain.", idiomatic: "On jiachen, he sacrificed to the Great Altar of Soil and Grain." },
  { zh: "除市門稅。", literal: "Market-gate taxes were abolished.", idiomatic: "Market-gate taxes were abolished." },
  { zh: "乙巳，享太廟，仍用鄭玄義，立太祖與二昭、二穆為五廟，其有德者別為祧廟，不毀。", literal: "On yisi, he offered at the Imperial Ancestral Temple, still following Zheng Xuan's interpretation; he established the Grand Ancestor with two zhao and two mu as five temples, and those of outstanding virtue had separate distant temples that were not destroyed.", idiomatic: "On yisi, he offered at the Imperial Ancestral Temple, still following Zheng Xuan's interpretation; he established the Grand Ancestor with two zhao and two mu as five temples, and those of outstanding virtue had separate distant temples that were never destroyed." },
  { zh: "辛亥，祀南郊。", literal: "On xinhai, he sacrificed at the southern suburb.", idiomatic: "On xinhai, he sacrificed at the southern suburb." },
  { zh: "壬子，立王后元氏。", literal: "On renzi, he installed Lady Yuan as queen.", idiomatic: "On renzi, he installed Lady Yuan as queen." },
  { zh: "後，魏文帝之女晉安公主也。", literal: "The queen was Princess Jin'an, daughter of Wei Emperor Wen.", idiomatic: "The queen was Princess Jin'an, daughter of Wei Emperor Wen." },
  { zh: "齊南安城主馮顯請降於周，周柱國宇文貴使豐州刺史太原郭彥將兵迎之，遂據南安。", literal: "Qi garrison commander of Nan'ancheng Feng Xian asked to surrender to Zhou; Zhou pillar of state Yuwen Gui sent Fengzhou Inspector Guo Yan of Taiyuan to lead troops to welcome him, and they then held Nan'an.", idiomatic: "Northern Qi's garrison commander of Nan'ancheng Feng Xian asked to surrender to Northern Zhou; pillar of state Yuwen Gui sent Fengzhou inspector Guo Yan of Taiyuan to lead troops to welcome him, and they then held Nan'an." },
  { zh: "吐谷渾為寇於周，攻涼、鄯、河三州。", literal: "Tuyuhun raided Zhou, attacking the three provinces of Liang, Shan, and He.", idiomatic: "Tuyuhun raided Northern Zhou, attacking Liang, Shan, and He provinces." },
  { zh: "秦州都督遣渭州刺史於翼赴援，翼不從。", literal: "The Qinzhou area commander sent Weizhou Inspector Yu Yi to the rescue; Yi would not go.", idiomatic: "The Qinzhou area commander sent Weizhou inspector Yu Yi to the rescue; Yi refused." },
  { zh: "僚屬鹹以為言，翼曰：「攻取之術，非夷俗所長。", literal: "His staff all spoke up; Yi said, \"The art of storming and seizing is not what barbarian custom excels at.", idiomatic: "His staff all remonstrated; Yi said, \"The art of storming and seizing is not what the barbarians excel at." },
  { zh: "此寇之來，不過抄掠邊牧耳。", literal: "This raid comes only to plunder the border pastures.", idiomatic: "This raid comes only to plunder the border pastures." },
  { zh: "掠而無獲，勢將自走。", literal: "If they plunder and gain nothing, the momentum will carry them away of themselves.", idiomatic: "If they plunder and gain nothing, they will withdraw on their own." },
  { zh: "勞師以往，必無所及。", literal: "To weary the army going after them will surely achieve nothing.", idiomatic: "To weary the army chasing them will achieve nothing." },
  { zh: "翼揣之已了，幸勿復言。", literal: "I have already reckoned this through—please speak no more of it.", idiomatic: "I have already reckoned this through—please speak no more of it." },
  { zh: "」數日，問至，果如翼所策。", literal: "\" Several days later reports arrived—it was exactly as Yi had foreseen.", idiomatic: "\" Several days later reports arrived—it was exactly as Yu Yi had foreseen." },
  { zh: "初，梁世祖以始興郡為東衡州，以歐陽頠為刺史。", literal: "Earlier, Liang Emperor Yuan made Shixing Commandery Eastern Hengzhou and made Ouyang Yi inspector.", idiomatic: "Earlier, Liang Emperor Yuan made Shixing Commandery into Eastern Hengzhou and made Ouyang Yi its inspector." },
  { zh: "久之，徙頠為郢州刺史，蕭勃留頠不遣。", literal: "After a long while Yi was transferred to be Yingzhou inspector; Xiao Bo detained Yi and would not let him go.", idiomatic: "After a long while Yi was transferred to Yingzhou inspector; Xiao Bo detained him and would not let him go." },
  { zh: "世祖以王琳代勃為廣州刺史，勃遣其將孫蕩監廣州，盡帥所部屯始興以避之。", literal: "Emperor Yuan had Wang Lin replace Bo as Guangzhou inspector; Bo sent his general Sun Dang to oversee Guangzhou and led all his followers to encamp at Shixing to avoid him.", idiomatic: "Emperor Yuan had Wang Lin replace Bo as Guangzhou inspector; Bo sent his general Sun Dang to oversee Guangzhou and led all his followers to encamp at Shixing to avoid him." },
  { zh: "頠別據一城，不往謁，閉門自守。", literal: "Yi separately held a walled city, did not go to call on him, and shut the gates to defend himself.", idiomatic: "Yi separately held a walled city, did not go to call on him, and shut the gates to defend himself." },
  { zh: "勃怒，遣兵襲之，盡取其貨財馬仗；", literal: "Bo was angry and sent troops to raid him, taking all his goods, wealth, horses, and weapons;", idiomatic: "Bo was furious and sent troops to raid him, seizing all his goods, wealth, horses, and weapons;" },
  { zh: "尋赦之，使復其所，與之結盟。", literal: "soon he pardoned him, restored what he had taken, and made alliance with him.", idiomatic: "soon he pardoned him, restored what he had taken, and made alliance with him." },
  { zh: "江陵陷，頠遂事勃。", literal: "When Jiangling fell, Yi thereupon served Bo.", idiomatic: "When Jiangling fell, Yi thereupon served Bo." },
  { zh: "二月，庚午，勃起兵於廣州，遣頠及其將傅泰、蕭孜為前軍。", literal: "In the second month, on gengwu, Bo raised troops at Guangzhou and sent Yi and his generals Fu Tai and Xiao Zi as the vanguard.", idiomatic: "In the second month, on gengwu, Bo raised troops at Guangzhou and sent Yi and his generals Fu Tai and Xiao Zi as the vanguard." },
  { zh: "孜，勃之從子也。", literal: "Zi was Bo's younger cousin.", idiomatic: "Zi was Bo's younger cousin." },
  { zh: "南江州刺史余孝頃以兵會之。", literal: "South Jiangzhou Inspector Yu Xiaoxiang joined him with troops.", idiomatic: "South Jiangzhou inspector Yu Xiaoxiang joined him with troops." },
  { zh: "詔平西將軍周文育帥諸軍討之。", literal: "An edict ordered General Who Pacifies the West Zhou Wenyu to lead the armies to campaign against them.", idiomatic: "An edict ordered general who pacifies the west Zhou Wenyu to lead the armies against them." },
  { zh: "癸酉，周王朝日於東郊；", literal: "On guiyou, the Zhou king performed the sun rite at the eastern suburb;", idiomatic: "On guiyou, the Northern Zhou king performed the sun rite at the eastern suburb;" },
  { zh: "戊寅，祭太社。", literal: "on wuyin he sacrificed to the Great Altar of Soil and Grain.", idiomatic: "on wuyin he sacrificed to the Great Altar of Soil and Grain." },
  { zh: "周楚公趙貴、衛公獨孤信故皆與太祖等夷，及晉公護專政，皆怏怏不服。", literal: "Zhou's Duke of Chu Zhao Gui and Duke of Wei Dugu Xin had long been equals with the Grand Ancestor; when Duke of Jin Hu monopolized government, all were sullen and would not submit.", idiomatic: "Northern Zhou's Duke of Chu Zhao Gui and Duke of Wei Dugu Xin had long been equals with the Grand Ancestor; when Duke of Jin Yuwen Hu monopolized government, all were sullen and would not submit." },
  { zh: "貴謀殺護，信止之；", literal: "Gui plotted to kill Hu; Xin stopped him;", idiomatic: "Gui plotted to kill Hu; Xin stopped him;" },
  { zh: "開府儀同三司宇文盛告之。", literal: "Acting Three Excellencies Yuwen Sheng reported it.", idiomatic: "Yuwen Sheng, equal in honor to the three dukes, reported it." },
  { zh: "丁亥，貴入朝，護執而殺之，免信官。", literal: "On dinghai, Gui entered court; Hu seized and killed him and stripped Xin of office.", idiomatic: "On dinghai, Gui entered court; Hu seized and killed him and stripped Xin of office." },
  { zh: "領軍將軍徐度出東關侵齊，戊子，至合肥，燒齊船三千艘。", literal: "Garrison-general Xu Du went out from Dongguan to raid Qi; on wuzi he reached Hefei and burned three thousand Qi ships.", idiomatic: "Garrison-general Xu Du went out from Dongguan to raid Northern Qi; on wuzi he reached Hefei and burned three thousand Qi ships." },
  { zh: "歐陽頠等出南康。", literal: "Ouyang Yi and the rest marched out from Nankang.", idiomatic: "Ouyang Yi and the rest marched out from Nankang." },
  { zh: "頠屯豫章之苦竹灘，傅泰據蹠口城，余孝頃遣其弟孝勵守郡城，自出豫章據石頭。", literal: "Yi encamped at Kuzhu Ford in Yuzhang; Fu Tai held Chikou Fortress; Yu Xiaoxiang sent his younger brother Xiaoli to guard the commandery seat while he himself went out from Yuzhang to hold Shitou.", idiomatic: "Yi encamped at Kuzhu Ford in Yuzhang; Fu Tai held Chikou Fortress; Yu Xiaoxiang sent his younger brother Xiaoli to guard the commandery seat while he himself went out from Yuzhang to hold Shitou." },
  { zh: "巴山太守熊曇朗誘頠共襲高州刺史黃法□；", literal: "Bashan Administrator Xiong Tanlang enticed Yi to join in attacking Gaozhou Inspector Huang Fa□;", idiomatic: "Bashan administrator Xiong Tanlang enticed Yi to join in attacking Gaozhou inspector Huang Fa□;" },
  { zh: "又語法□，約共破頠，且曰：「事捷，與我馬仗。", literal: "he also spoke to Fa□, agreeing to break Yi together, and said, \"If the affair succeeds, give me horses and weapons.", idiomatic: "he also spoke to Fa□, agreeing to break Yi together, and said, \"If the affair succeeds, give me horses and weapons." },
  { zh: "」遂出軍，與頠俱進。", literal: "\" He then sent out troops and advanced together with Yi.", idiomatic: "\" He then sent out troops and advanced together with Yi." },
  { zh: "至法□城下，曇朗陽敗走，法□乘之，頠失援而走，曇朗取其馬仗，歸於巴山。", literal: "When they reached Fa□'s walls, Tanlang pretended defeat and fled; Fa□ pressed the pursuit; Yi lost support and fled; Tanlang took his horses and weapons and returned to Bashan.", idiomatic: "When they reached Fa□'s walls, Tanlang feigned defeat and fled; Fa□ pressed the pursuit; Yi lost support and fled; Tanlang took his horses and weapons and returned to Bashan." },
  { zh: "周文育軍少船，余孝頃有船在上牢，文育遣軍主焦僧度襲之，盡取以歸，仍於豫章立柵。", literal: "Zhou Wenyu's army had few boats; Yu Xiaoxiang had boats at Shanglao; Wenyu sent army commander Jiao Sengdu to raid them, took them all, and still built palisades at Yuzhang.", idiomatic: "Zhou Wenyu's army had few boats; Yu Xiaoxiang had boats at Shanglao; Wenyu sent army commander Jiao Sengdu to raid them, took them all, and built palisades at Yuzhang." },
  { zh: "軍中食盡，諸將欲退。", literal: "Food in the army was exhausted and the generals wished to withdraw.", idiomatic: "Food in the army ran out and the generals wished to withdraw." },
  { zh: "文育不許，使人間行遺周迪書，約為兄弟。", literal: "Wenyu would not allow it and sent a man by secret route with a letter to Zhou Di, proposing brotherhood.", idiomatic: "Wenyu refused and sent a man by secret route with a letter to Zhou Di, proposing brotherhood." },
  { zh: "迪得書甚喜，許饋以糧。", literal: "Di received the letter and was greatly pleased; he promised to supply grain.", idiomatic: "Di received the letter and was greatly pleased; he promised to supply grain." },
  { zh: "於是文育分遣老弱乘故船沿流俱下，燒豫章柵，偽若遁去者。", literal: "Thereupon Wenyu separately sent the old and weak aboard their old boats downstream together, burned the Yuzhang palisades, and feigned flight.", idiomatic: "Thereupon Wenyu sent the old and weak aboard their old boats downstream, burned the Yuzhang palisades, and feigned flight." },
  { zh: "孝頃望之，大喜，不復設備。", literal: "Xiaoxiang watched them and was greatly pleased, and set no further defenses.", idiomatic: "Xiaoxiang watched them and was delighted, and set no further defenses." },
  { zh: "文育由間道兼行，據芊韶，芊韶上流則歐陽頠、蕭孜，下流則傅泰、余孝頃營，文育據其中間，築城饗士，頠等大駭。", literal: "Wenyu by a secret route marched at double pace and seized Qianshao; upstream at Qianshao were Ouyang Yi and Xiao Zi, downstream the camps of Fu Tai and Yu Xiaoxiang; Wenyu held the middle, built a fort, and feasted his men; Yi and the rest were greatly alarmed.", idiomatic: "Wenyu by a secret route marched at double pace and seized Qianshao; upstream were Ouyang Yi and Xiao Zi, downstream the camps of Fu Tai and Yu Xiaoxiang; Wenyu held the middle, built a fort, and feasted his men; Yi and the rest were terrified." },
  { zh: "頠退入泥溪，文育遣嚴威將軍周鐵虎等襲頠，癸巳，擒之。", literal: "Yi withdrew into Nixi Creek; Wenyu sent Stern Might General Zhou Tiehu and others to strike Yi; on guisi they captured him.", idiomatic: "Yi withdrew into Nixi Creek; Wenyu sent stern might general Zhou Tiehu and others to strike Yi; on guisi they captured him." },
  { zh: "文育盛陳兵甲，與頠乘舟而宴，巡蹠口城下，使其將丁法洪攻泰，擒之，孜、孝頃退走。", literal: "Wenyu displayed arms in full array, feasted with Yi aboard a boat, and circled below Chikou Fortress; he had his general Ding Fahong attack Tai and capture him; Zi and Xiaoxiang fled.", idiomatic: "Wenyu displayed arms in full array, feasted with Yi aboard a boat, and circled below Chikou Fortress; he had his general Ding Fahong attack Tai and capture him; Zi and Xiaoxiang fled." },
  { zh: "甲午，周以於謹為太傅，大宗伯侯莫陳崇為太保，晉公護為大塚宰，柱國武川賀蘭祥為大司馬，高陽公達奚武為大司寇。", literal: "On jiawu, Zhou made Yu Jin Grand Tutor, Grand Director of the Masses Houmochen Chong Grand Guardian, Duke of Jin Hu Grand Chief Minister, pillar of state Helan Xiang of Wuchuan Grand Marshal, and Duke Wu of Gaoyang Daxi Grand Judge.", idiomatic: "On jiawu, Northern Zhou made Yu Jin grand tutor, grand director of the masses Houmochen Chong grand guardian, Duke of Jin Yuwen Hu grand chief minister, pillar of state Helan Xiang of Wuchuan grand marshal, and Duke Wu of Gaoyang Daxi grand judge." },
  { zh: "周人殺魏恭帝。", literal: "Zhou men killed the Wei Emperor Gong.", idiomatic: "Northern Zhou killed the Wei Emperor Gong." },
  { zh: "三月，庚子，周文育送歐陽頠、傅泰於建康。", literal: "In the third month, on gengzi, Zhou Wenyu sent Ouyang Yi and Fu Tai to Jiankang.", idiomatic: "In the third month, on gengzi, Zhou Wenyu sent Ouyang Yi and Fu Tai to Jiankang." },
  { zh: "丞相霸先與頠有舊，釋而厚待之。", literal: "Chancellor Baxian had old ties with Yi; he released him and treated him generously.", idiomatic: "Chancellor Chen Baxian had old ties with Yi; he released him and treated him generously." },
  { zh: "周晉公護以趙景公獨孤信名重，不欲顯誅之，己酉，逼令自殺。", literal: "Zhou's Duke of Jin Hu, because Duke Jing of Zhao Dugu Xin was of great renown, did not wish to execute him openly; on jiyou he forced him to kill himself.", idiomatic: "Northern Zhou's Duke of Jin Yuwen Hu, because Duke Jing of Zhao Dugu Xin was of great renown, did not wish to execute him openly; on jiyou he forced him to kill himself." },
  { zh: "甲辰，以司空王琳為湘、郢二州刺史。", literal: "On jiachen, Minister of Works Wang Lin was made inspector of Xiang and Ying provinces.", idiomatic: "On jiachen, minister of works Wang Lin was made inspector of Xiang and Ying provinces." },
  { zh: "曲江侯勃在南康，聞歐陽頠等敗，軍中忷懼。", literal: "Marquis Bo of Qujiang was at Nankang; hearing Ouyang Yi and the rest were defeated, the army was alarmed and afraid.", idiomatic: "Marquis Bo of Qujiang was at Nankang; hearing Ouyang Yi and the rest were defeated, the army panicked." },
  { zh: "甲寅，德州刺史陳法武、前衡州刺史譚世遠攻勃，殺之。", literal: "On jiayin, Dezhou Inspector Chen Fawu and former Hengzhou Inspector Tan Shiyuan attacked Bo and killed him.", idiomatic: "On jiayin, Dezhou inspector Chen Fawu and former Hengzhou inspector Tan Shiyuan attacked Bo and killed him." },
  { zh: "夏，四月，己卯，鑄四柱錢，一當二十。", literal: "In summer, the fourth month, on jimao, four-pillar cash was cast, each counting for twenty.", idiomatic: "In summer, the fourth month, on jimao, four-pillar cash was cast, each worth twenty." },
  { zh: "齊遣使請和。", literal: "Qi sent envoys seeking peace.", idiomatic: "Northern Qi sent envoys seeking peace." },
  { zh: "壬午，周王謁成陵；", literal: "On renwu, the Zhou king visited Cheng Mausoleum;", idiomatic: "On renwu, the Northern Zhou king visited Cheng Mausoleum;" },
  { zh: "乙酉，還宮。", literal: "on yiyou he returned to the palace.", idiomatic: "on yiyou he returned to the palace." },
  { zh: "齊以太師斛律金為右丞相，前大將軍可朱渾道元為太傅，開府儀同三司賀拔仁為太保，尚書令常山王演為司空，錄尚書事長廣王湛為尚書令，右僕射楊愔為左僕射，仍加開府儀同三司。", literal: "Qi made Grand Preceptor Hulu Jin Right Chancellor, former Grand General Kezhunhun Daoyuan Grand Tutor, Acting Three Excellencies Heba Ren Grand Guardian, Secretariat Director Prince Yan of Changshan Minister of Works, Recorder of the Masters of Writing Prince Zhan of Changgung Director of the Masters of Writing, Right Vice Director Yang Yin Left Vice Director, still with Acting Three Excellencies added.", idiomatic: "Northern Qi made grand preceptor Hulu Jin right chancellor, former grand general Kezhunhun Daoyuan grand tutor, Heba Ren, equal in honor to the three dukes, grand guardian, secretariat director Prince Yan of Changshan minister of works, recorder Prince Zhan of Changgung director of the masters of writing, right vice director Yang Yin left vice director, still with the honor of the three dukes." },
  { zh: "並省尚書右僕射崔暹為左僕射，主黨王渙錄尚書事。", literal: "The merged provinces' Right Vice Director Cui Xian was made Left Vice Director, and chief party member Wang Huan recorder of the masters of writing.", idiomatic: "The merged provinces' right vice director Cui Xian was made left vice director, and chief party member Wang Huan recorder of the masters of writing." },
  { zh: "丁亥，周王享太廟。", literal: "On dinghai, the Zhou king offered at the Imperial Ancestral Temple.", idiomatic: "On dinghai, the Northern Zhou king offered at the Imperial Ancestral Temple." },
  { zh: "壬辰，改四柱錢一當十；", literal: "On renchen, four-pillar cash was changed to count for ten;", idiomatic: "On renchen, four-pillar cash was changed to count for ten;" },
  { zh: "丙申，復閉細錢。", literal: "on bingshen small cash was again closed.", idiomatic: "on bingshen small cash was again abolished." },
  { zh: "故曲江侯勃主帥蘭敳襲殺譚世遠，軍主夏侯明徹殺敳，持勃首降。", literal: "Former Marquis Bo of Qujiang's commander Lan Ai raided and killed Tan Shiyuan; army commander Xiahou Mingche killed Ai and presented Bo's head in surrender.", idiomatic: "Former Marquis Bo of Qujiang's commander Lan Ai raided and killed Tan Shiyuan; army commander Xiahou Mingche killed Ai and presented Bo's head in surrender." },
  { zh: "勃故記室李賀藏奉懷安侯任據廣州。", literal: "Bo's former recorder Li He hid and supported Marquis Ren of Huai'an in seizing Guangzhou.", idiomatic: "Bo's former recorder Li He hid and supported Marquis Ren of Huai'an in seizing Guangzhou." },
  { zh: "蕭孜、余孝頃猶據石頭，為兩城，各居其一，多設船艦，夾水而陳。", literal: "Xiao Zi and Yu Xiaoxiang still held Shitou as two walled cities, each occupying one; they set out many ships and arrayed them along the water.", idiomatic: "Xiao Zi and Yu Xiaoxiang still held Shitou as two walled cities, each occupying one; they set out many ships and arrayed them along the water." },
  { zh: "丞相霸先遣平南將軍侯安都助周文育擊之。", literal: "Chancellor Baxian sent General Who Pacifies the South Hou Andu to assist Zhou Wenyu in attacking them.", idiomatic: "Chancellor Chen Baxian sent general who pacifies the south Hou Andu to assist Zhou Wenyu in attacking them." },
  { zh: "戊戌，安都潛師夜燒其船艦，文育帥水軍、安都帥步騎進攻之；", literal: "On wuxu, Andu secretly led troops by night to burn their ships; Wenyu led the navy and Andu led foot and horse in the assault;", idiomatic: "On wuxu, Andu secretly led troops by night to burn their ships; Wenyu led the navy and Andu led foot and horse in the assault;" },
  { zh: "蕭孜出降，孝頃逃歸新吳，文育等引兵還。", literal: "Xiao Zi came out and surrendered; Xiaoxiang fled back to Xinwu; Wenyu and the rest led the army back.", idiomatic: "Xiao Zi surrendered; Xiaoxiang fled to Xinwu; Wenyu and the rest led the army back." },
  { zh: "丞相霸先以歐陽頠聲著南土，復以頠為衡州刺史，使討嶺南。", literal: "Chancellor Baxian, because Ouyang Yi's fame stood in the southern lands, again made Yi Hengzhou inspector and sent him to campaign in Lingnan.", idiomatic: "Chancellor Chen Baxian, because Ouyang Yi's fame stood in the south, again made him Hengzhou inspector and sent him to campaign in Lingnan." },
  { zh: "未至，其子紇已克始興，頠至嶺南，諸郡皆降，遂克廣州，嶺南悉平。", literal: "Before he arrived, his son He had already taken Shixing; when Yi reached Lingnan all commanderies surrendered; he then took Guangzhou and all Lingnan was pacified.", idiomatic: "Before he arrived, his son He had already taken Shixing; when Yi reached Lingnan all commanderies surrendered; he then took Guangzhou and all Lingnan was pacified." },
  { zh: "周儀同三司齊軌謂御正中大夫薛善曰：「軍國之政，當歸天子，何得猶在權門！", literal: "Zhou's Acting Three Excellencies Qi Gui said to Chief Rectifier of the Center Xue Shan, \"Military and state affairs ought to return to the Son of Heaven—how can they still rest in the power-holders' gate!", idiomatic: "Northern Zhou's Qi Gui, equal in honor to the three dukes, said to chief rectifier Xue Shan, \"Military and state affairs ought to return to the Son of Heaven—how can they still rest with the power-holders!" },
  { zh: "」善以告晉公護，護殺之，以善為中外府司馬。", literal: "\" Shan reported this to Duke of Jin Hu; Hu killed Gui and made Shan marshal of the inner and outer offices.", idiomatic: "\" Shan reported this to Duke of Jin Yuwen Hu; Hu killed Gui and made Shan marshal of the inner and outer offices." },
  { zh: "五月，戊辰，余孝頃遣使詣丞相府乞降。", literal: "In the fifth month, on wuchen, Yu Xiaoxiang sent envoys to the chancellor's office begging to surrender.", idiomatic: "In the fifth month, on wuchen, Yu Xiaoxiang sent envoys to the chancellor's office begging to surrender." },
  { zh: "王琳既不就征，大治舟艦，將攻陳霸先；", literal: "Wang Lin, having refused the summons, greatly repaired boats and ships and was about to attack Chen Baxian;", idiomatic: "Wang Lin, having refused the summons, greatly repaired boats and ships and was about to attack Chen Baxian;" },
  { zh: "六月，戊寅，霸先以開府儀同三司侯安都為西道都督，周文育為南道都督，將舟師二萬會武昌以擊之。", literal: "In the sixth month, on wuyin, Baxian made Acting Three Excellencies Hou Andu western-route commander and Zhou Wenyu southern-route commander, and led twenty thousand of the fleet to join at Wuchang to strike him.", idiomatic: "In the sixth month, on wuyin, Chen Baxian made Hou Andu, equal in honor to the three dukes, western-route commander and Zhou Wenyu southern-route commander, and led twenty thousand of the fleet to join at Wuchang to strike him." },
  { zh: "秋，七月，辛亥，周王享太廟。", literal: "In autumn, the seventh month, on xinhai, the Zhou king offered at the Imperial Ancestral Temple.", idiomatic: "In autumn, the seventh month, on xinhai, the Northern Zhou king offered at the Imperial Ancestral Temple." },
  { zh: "河南、北大蝗。", literal: "Henan and the north suffered great locust plagues.", idiomatic: "Henan and the north suffered great locust plagues." },
  { zh: "齊主問於魏郡丞崔叔瓚曰：「何故致蝗？", literal: "The Qi ruler asked Wei Commandery Assistant Cui Shuchan, \"What brings locusts?", idiomatic: "Gao Yang asked Wei Commandery assistant Cui Shuchan, \"What brings locusts?" },
  { zh: "」對曰：「《五行志》：土功不時，蝗蟲為災。", literal: "\" He answered, \"The Treatise on the Five Phases says: when earthworks are untimely, locusts become disaster.", idiomatic: "\" He answered, \"The Treatise on the Five Phases says: when earthworks are untimely, locusts become disaster." },
  { zh: "今外築長城，內興三台，殆以此乎！", literal: "Now you build the Long Wall without and raise the Three Terraces within—perhaps this is it!", idiomatic: "Now you build the Long Wall without and raise the Three Terraces within—perhaps this is it!" },
  { zh: "」齊主大怒，使左右毆之，擢其發，以溷沃其頭，曳足以出。", literal: "\" The Qi ruler was greatly angry and had his attendants beat him, tore out his hair, poured night soil over his head, and dragged him out by the feet.", idiomatic: "\" Gao Yang was furious and had his attendants beat him, tore out his hair, poured night soil over his head, and dragged him out by the feet." },
  { zh: "叔瓚，季舒之兄也。", literal: "Shuchan was the elder brother of Jishu.", idiomatic: "Shuchan was the elder brother of Jishu." },
  { zh: "八月，丁卯，周人歸梁世祖之柩及諸將家屬千餘人於王琳。", literal: "In the eighth month, on dingmao, Zhou men returned Liang Emperor Yuan's coffin and more than a thousand family members of the generals to Wang Lin.", idiomatic: "In the eighth month, on dingmao, Northern Zhou returned Liang Emperor Yuan's coffin and more than a thousand family members of the generals to Wang Lin." },
  { zh: "戊辰，周王祭太社。", literal: "On wuchen, the Zhou king sacrificed to the Great Altar of Soil and Grain.", idiomatic: "On wuchen, the Northern Zhou king sacrificed to the Great Altar of Soil and Grain." },
  { zh: "甲午，進丞相霸先位太傅，加黃鉞、殊禮，贊拜不名。", literal: "On jiawu, Chancellor Baxian was advanced to Grand Tutor, with the yellow battle-axe and extraordinary rites, and approval without naming.", idiomatic: "On jiawu, Chancellor Chen Baxian was advanced to grand tutor, with the yellow battle-axe and extraordinary rites, and approval without naming." },
  { zh: "九月，辛丑，進丞相為相國，總百揆，封陳公，備九錫，陳國置百司。", literal: "In the ninth month, on xinchou, the chancellor was advanced to chief minister, overseeing all affairs; he was enfeoffed as Duke of Chen with the full Nine Bestowals, and the state of Chen established the hundred offices.", idiomatic: "In the ninth month, on xinchou, the chancellor was advanced to chief minister overseeing all affairs; he was enfeoffed as Duke of Chen with the full Nine Bestowals, and the state of Chen established the hundred offices." },
  { zh: "周孝愍帝性剛果，惡晉公護之專權。", literal: "Northern Zhou Emperor Xiaomin was firm and resolute by nature and hated Duke of Jin Hu's monopoly of power.", idiomatic: "Emperor Xiaomin of Northern Zhou was firm and resolute by nature and hated Duke of Jin Yuwen Hu's monopoly of power." },
  { zh: "司會李植自太祖時為相府司錄，參掌朝政，軍司馬孫恆亦久居權要，及護執政，植、恆恐不見容，乃與宮伯乙弗鳳、賀拔提等共譖之於周王。", literal: "Director of Accounts Li Zhi had been chief clerk of the chancellor's office since the Grand Ancestor's time and shared control of court affairs; army marshal Sun Heng had also long held crucial power; when Hu took government, Zhi and Heng feared they would not be tolerated and together with palace guard Yifu Feng, Heba Ti, and others slandered Hu to the Zhou king.", idiomatic: "Director of accounts Li Zhi had been chief clerk of the chancellor's office since the Grand Ancestor's time and shared control of court affairs; army marshal Sun Heng had also long held crucial power; when Yuwen Hu took government, Zhi and Heng feared they would not be tolerated and together with palace guard Yifu Feng, Heba Ti, and others slandered Hu to the Zhou king." },
  { zh: "植、恆曰：「護自誅趙貴以來，威權日盛，謀臣宿將，爭往附之，大小之政，皆決於護。", literal: "Zhi and Heng said, \"Since Hu killed Zhao Gui, his awesome power grows daily; strategists and veteran generals vie to attach themselves to him; great and small affairs are all decided by Hu.", idiomatic: "Zhi and Heng said, \"Since Yuwen Hu killed Zhao Gui, his power grows daily; strategists and veteran generals vie to attach themselves to him; great and small affairs are all decided by Hu." },
  { zh: "以臣觀之，將不守臣節，願陛下早圖之！", literal: "In your servant's view, he will not keep the minister's measure—may Your Majesty plan early!", idiomatic: "In our view, he will not keep the minister's measure—may Your Majesty act early!" },
  { zh: "」王以為然。", literal: "\" The king thought it so.", idiomatic: "\" The king agreed." },
  { zh: "鳳、提曰：「以先王之明，猶委植、恆以朝政，今以事付二人，何患不成！", literal: "Feng and Ti said, \"With the late king's clarity, he still entrusted Zhi and Heng with court affairs; if you now entrust the affair to these two men, what worry that it will not succeed!", idiomatic: "Feng and Ti said, \"With the late king's clarity, he still entrusted Zhi and Heng with court affairs; if you now entrust the affair to these two men, what worry that it will not succeed!" },
  { zh: "且護常自比周公，臣聞周公攝政七年，陛下安能七年邑邑如此乎！", literal: "Moreover Hu often compares himself to the Duke of Zhou; your servant has heard the Duke of Zhou held regency seven years—can Your Majesty endure seven years of such distress!", idiomatic: "Moreover Hu often compares himself to the Duke of Zhou; we have heard the Duke of Zhou held regency seven years—can Your Majesty endure seven years of such distress!" },
  { zh: "」王愈信之，數引武士於後園講習，為執縛之勢。", literal: "\" The king believed all the more, repeatedly drew warriors to the rear garden for drill, and practiced the posture of seizing and binding.", idiomatic: "\" The king believed all the more, repeatedly drew warriors to the rear garden for drill, and practiced seizing and binding." },
  { zh: "植等又引宮伯張光洛同謀，光洛以告護。", literal: "Zhi and the rest also drew palace guard Zhang Guangluo into the plot; Guangluo reported it to Hu.", idiomatic: "Zhi and the rest also drew palace guard Zhang Guangluo into the plot; Guangluo reported it to Yuwen Hu." },
  { zh: "護乃出植為梁州刺史，恆為潼州刺史，欲散其謀。", literal: "Hu then sent Zhi out as Liangzhou inspector and Heng as Tongzhou inspector, wishing to scatter their plot.", idiomatic: "Yuwen Hu then sent Zhi out as Liangzhou inspector and Heng as Tongzhou inspector, wishing to scatter their plot." },
  { zh: "後王思植等，每欲召之，護泣諫曰：「天下至親，無過兄弟，若兄弟尚相疑，它人誰可信者！", literal: "Later the king missed Zhi and the rest and wished each time to summon them; Hu wept and remonstrated, \"Under Heaven the closest kin is none beyond brothers; if brothers still suspect one another, whom among others can be trusted!", idiomatic: "Later the king missed Zhi and the rest and wished each time to summon them; Hu wept and remonstrated, \"Under Heaven the closest kin is none beyond brothers; if brothers still suspect one another, whom among others can be trusted!" },
  { zh: "太祖以陛下富於春秋，屬臣後事，臣情兼家國，實願竭其股肱。", literal: "The Grand Ancestor, seeing Your Majesty rich in years, entrusted the aftermath to your servant; my feeling joins family and state—I truly wish to exhaust my limbs in service.", idiomatic: "The Grand Ancestor, seeing Your Majesty young in years, entrusted the aftermath to me; my feeling joins family and state—I truly wish to exhaust myself in your service." },
  { zh: "若陛下親鑒萬機，威加四海，臣死之日，猶生之年。", literal: "If Your Majesty personally oversees the myriad affairs and your awesomeness fills the four seas, the day of your servant's death will still be a day of life.", idiomatic: "If Your Majesty personally oversees the myriad affairs and your awesomeness fills the four seas, the day I die will still be a day of life." },
  { zh: "但恐除臣之後，奸回得志，非唯不利陛下，亦將傾覆社稷，使臣無面目見太祖於九泉。", literal: "Yet I fear that after removing your servant, treacherous men will have their way—not only to Your Majesty's harm but also to overturning the altars of soil and grain, leaving your servant no face to meet the Grand Ancestor in the nine springs.", idiomatic: "Yet I fear that after removing me, traitors will have their way—not only to Your Majesty's harm but to overturning the realm, leaving me no face to meet the Grand Ancestor in the grave." },
  { zh: "且臣既為天子之兄，位至宰相，尚復何求！", literal: "Moreover your servant is already the Son of Heaven's elder brother and has reached chancellor—what more is there to seek!", idiomatic: "Moreover I am already the Son of Heaven's elder brother and have reached chancellor—what more is there to seek!" },
  { zh: "願陛下勿信讒臣之言，疏棄骨肉。", literal: "May Your Majesty not believe slanderers' words and cast aside flesh and bone.", idiomatic: "May Your Majesty not believe slanderers' words and cast aside flesh and bone." },
  { zh: "」王乃止不召，而心猶疑之。", literal: "\" The king then stopped summoning them, yet his heart still doubted.", idiomatic: "\" The king then stopped summoning them, yet his heart still doubted." },
  { zh: "鳳等益懼，密謀滋甚，刻日召群公入宴，因執護誅之；", literal: "Feng and the rest grew more afraid; their secret plot deepened; they set a day to summon the dukes to enter for a feast and thereupon seize Hu and execute him;", idiomatic: "Feng and the rest grew more afraid; their secret plot deepened; they set a day to summon the dukes to a feast and thereupon seize Hu and execute him;" },
  { zh: "張光洛又以告護。", literal: "Zhang Guangluo again reported it to Hu.", idiomatic: "Zhang Guangluo again reported it to Yuwen Hu." },
  { zh: "護乃召柱國賀蘭祥、領軍尉遲綱等謀之，祥等勸護廢立。", literal: "Hu then summoned pillars of state Helan Xiang, garrison-general Yuchi Gang, and others to plot; Xiang and the rest urged Hu to depose and establish.", idiomatic: "Yuwen Hu then summoned pillar of state Helan Xiang, garrison-general Yuchi Gang, and others to plot; Xiang and the rest urged Hu to depose and establish." },
  { zh: "時綱總領禁兵，護遣綱入宮召鳳等議事，及至，以次執送護第，因罷散宿衛兵。", literal: "At that time Gang commanded the forbidden troops; Hu sent Gang into the palace to summon Feng and the rest to discuss affairs; when they arrived, he seized them in order and sent them to Hu's residence, and thereupon dismissed the palace guard.", idiomatic: "At that time Gang commanded the palace guard; Hu sent Gang into the palace to summon Feng and the rest; when they arrived, he seized them in order and sent them to Hu's residence, and dismissed the palace guard." },
  { zh: "王方悟，獨在內殿，令宮人執兵自守。", literal: "The king only then understood; alone in the inner hall, he ordered palace women to take arms and defend themselves.", idiomatic: "The king only then understood; alone in the inner hall, he ordered palace women to take arms and defend themselves." },
  { zh: "護遣賀蘭祥逼王遜位，幽於舊第。", literal: "Hu sent Helan Xiang to force the king to yield the throne and confined him in his old residence.", idiomatic: "Hu sent Helan Xiang to force the king to abdicate and confined him in his old residence." },
  { zh: "悉召公卿公議，廢王為略陽公，迎立岐州刺史寧都公毓。", literal: "He summoned all the dukes and ministers for public deliberation, deposed the king as Duke of Lueyang, and welcomed Duke Yu of Ningdu as inspector of Qizhou to establish him.", idiomatic: "He summoned all the dukes and ministers for public deliberation, deposed the king as Duke of Lueyang, and welcomed Duke Yu of Ningdu, Qizhou inspector, to establish him." },
  { zh: "公卿皆曰：「此公之家事，敢不唯命是聽！", literal: "The dukes and ministers all said, \"This is the duke's family affair—we dare not do other than heed your command!", idiomatic: "The dukes and ministers all said, \"This is the duke's family affair—we dare not do other than heed your command!" },
  { zh: "」乃斬鳳等於門外，孫恆亦伏誅。", literal: "\" He then beheaded Feng and the rest outside the gate; Sun Heng also suffered execution.", idiomatic: "\" He then beheaded Feng and the rest outside the gate; Sun Heng was also executed." },
  { zh: "時李植父柱國大將軍遠鎮弘農，護召遠及植還朝，遠疑有變，沈吟久之，乃曰：「大丈夫寧為忠鬼，安可作叛臣邪！", literal: "At that time Li Zhi's father, pillar of state and grand general Yuan, was garrisoning Hongnong; Hu summoned Yuan and Zhi back to court; Yuan suspected trouble, hesitated long, and then said, \"A great man would rather be a loyal ghost—how could he become a rebel minister!", idiomatic: "At that time Li Zhi's father, pillar of state and grand general Li Yuan, was garrisoning Hongnong; Hu summoned Yuan and Zhi back to court; Yuan suspected trouble, hesitated long, and then said, \"A great man would rather be a loyal ghost—how could he become a rebel minister!" },
  { zh: "」遂就征。", literal: "\" He thereupon answered the summons.", idiomatic: "\" He thereupon answered the summons." },
  { zh: "既至長安，護以遠功名素重，猶欲全之。", literal: "When he reached Chang'an, Hu, because Yuan's fame and merit had long been weighty, still wished to spare him.", idiomatic: "When he reached Chang'an, Hu, because Li Yuan's fame and merit had long been weighty, still wished to spare him." },
  { zh: "引與相見，謂之曰：「公兒遂有異謀，非止屠戮護身，乃是傾危宗社。", literal: "He led him in to meet and said to him, \"Your son indeed had a different plot—not only to slaughter Hu's person but to overturn the ancestral altars.", idiomatic: "He led him in to meet and said to him, \"Your son indeed had a different plot—not only to kill me but to overturn the state." },
  { zh: "叛臣賊子，理宜同疾，公可早為之所。", literal: "Rebel ministers and traitor sons by right should share the hatred—you may act early against him.", idiomatic: "Rebel ministers and traitor sons by right should share the hatred—you may act early against him." },
  { zh: "」乃以植付遠。", literal: "\" He then handed Zhi over to Yuan.", idiomatic: "\" He then handed Zhi over to Yuan." },
  { zh: "遠素愛植，植又口辯，自陳初無此謀。", literal: "Yuan had always loved Zhi; Zhi was also glib of tongue and declared he had had no such plot at first.", idiomatic: "Yuan had always loved Zhi; Zhi was also glib and declared he had had no such plot at first." },
  { zh: "遠謂為信然，詰朝，將植謁護。", literal: "Yuan took it as true; at dawn the next day he was about to lead Zhi to call on Hu.", idiomatic: "Yuan believed him; at dawn the next day he was about to lead Zhi to call on Hu." },
  { zh: "護謂植已死，左右白植亦在門。", literal: "Hu thought Zhi was already dead; attendants reported Zhi was also at the gate.", idiomatic: "Hu thought Zhi was already dead; attendants reported Zhi was also at the gate." },
  { zh: "護大怒曰：「陽平公不信我！", literal: "Hu was greatly angry and said, \"Duke of Yangping does not trust me!", idiomatic: "Hu was furious and said, \"Duke of Yangping does not trust me!" },
  { zh: "」乃召入，仍命遠同坐，令略陽公與植相質於遠前。", literal: "\" He then summoned them in, still ordered Yuan to sit together, and had Duke of Lueyang and Zhi confront each other before Yuan.", idiomatic: "\" He then summoned them in, ordered Yuan to sit with him, and had Duke of Lueyang and Zhi confront each other before Yuan." },
  { zh: "植辭窮，謂略陽公曰：「本為此謀，欲安社稷，利至尊耳！", literal: "Zhi's words were exhausted; he said to Duke of Lueyang, \"This plot was originally to settle the altars of soil and grain and benefit the supreme one alone!", idiomatic: "Zhi was cornered; he said to Duke of Lueyang, \"This plot was originally to settle the realm and benefit Your Majesty alone!" },
  { zh: "今日至此，何事云云！", literal: "Today it has come to this—what is all this talk!", idiomatic: "Today it has come to this—what is all this talk!" },
  { zh: "」遠聞之，自投於床曰：「若爾，誠合萬死。", literal: "\" Yuan heard it and threw himself on the bed, saying, \"If so, you truly deserve ten thousand deaths.", idiomatic: "\" Yuan heard it and threw himself on the bed, saying, \"If so, you truly deserve ten thousand deaths." },
  { zh: "」於是護乃害植，並逼遠令自殺。", literal: "\" Thereupon Hu killed Zhi and also forced Yuan to kill himself.", idiomatic: "\" Thereupon Hu killed Zhi and also forced Yuan to kill himself." },
  { zh: "植弟叔詣、叔謙、叔讓亦死，餘子以幼得免。", literal: "Zhi's younger brothers Shuji, Shuqian, and Shurang also died; the remaining sons were spared because they were young.", idiomatic: "Zhi's younger brothers Shuji, Shuqian, and Shurang also died; the remaining sons were spared because they were young." },
  { zh: "初，遠弟開府儀同三司穆知植非保家之主，每勸遠除之，遠不能用。", literal: "Earlier, Yuan's younger brother Acting Three Excellencies Mu knew Zhi was not one who would preserve the family and repeatedly urged Yuan to remove him; Yuan could not use the counsel.", idiomatic: "Earlier, Yuan's younger brother Mu, equal in honor to the three dukes, knew Zhi would not preserve the family and repeatedly urged Yuan to remove him; Yuan would not listen." },
  { zh: "及遠臨刑，泣謂穆曰：「吾不用汝言，以至此！", literal: "When Yuan faced execution, he wept and said to Mu, \"I did not use your words—and so it has come to this!", idiomatic: "When Yuan faced execution, he wept and said to Mu, \"I did not heed you—and so it has come to this!" },
  { zh: "」穆當從坐，以前言獲免，除名為民，及其子弟亦免官。", literal: "\" Mu should have shared the punishment, but because of his earlier words he was spared, struck from the registers and made a commoner, and his sons and younger brothers were also removed from office.", idiomatic: "\" Mu should have shared the punishment, but because of his earlier warning he was spared, struck from the registers and made a commoner, and his sons and younger brothers were also removed from office." },
  { zh: "植弟淅州刺史基，尚義歸公主，當從坐，穆請以二子代基命，護兩釋之。", literal: "Zhi's younger brother Ji, Xizhou inspector, had married Princess Yigui and should have shared the punishment; Mu asked to substitute his two sons for Ji's life; Hu released both.", idiomatic: "Zhi's younger brother Ji, Xizhou inspector, had married Princess Yigui and should have shared the punishment; Mu asked to substitute his two sons for Ji's life; Hu released both." },
  { zh: "後月餘，護弒略陽公，黜王后元氏為尼。", literal: "More than a month later, Hu murdered Duke of Lueyang and demoted Queen Lady Yuan to be a nun.", idiomatic: "More than a month later, Yuwen Hu murdered Duke of Lueyang Yuwen Jue and demoted Queen Lady Yuan to be a nun." },
  { zh: "癸亥，寧都公自岐州至長安，甲子，即天王位，大赦。", literal: "On guihai, Duke of Ningdu came from Qizhou to Chang'an; on jiazi he took the Heavenly Kingship and proclaimed a general amnesty.", idiomatic: "On guihai, Duke of Ningdu Yuwen Yu came from Qizhou to Chang'an; on jiazi he took the Heavenly Kingship and proclaimed a general amnesty." },
  { zh: "冬，十月，戊辰，進陳公爵為王。", literal: "In winter, the tenth month, on wuchen, the Duke of Chen was advanced to king.", idiomatic: "In winter, the tenth month, on wuchen, Duke of Chen Chen Baxian was advanced to king." },
  { zh: "辛未，梁敬帝禪位於陳。", literal: "On xinwei, Liang Emperor Jing abdicated the throne to Chen.", idiomatic: "On xinwei, Emperor Jing of Liang abdicated the throne to Chen." },
  { zh: "癸酉，周魏武公李弼卒。", literal: "On guiyou, Zhou's Duke Wu of Wei Li Bi died.", idiomatic: "On guiyou, Northern Zhou's Duke Wu of Wei Li Bi died." },
  { zh: "陳王使中書舍人劉師知引宣猛將軍沈恪勒兵入宮，衛送梁主如別宮，恪排闥見王，叩頭謝曰：「恪身經事蕭氏，今日不忍見此。", literal: "The Chen king sent Masters of Writing Attendant Liu Shizhi to lead Fierce-proclamation General Shen Ke with troops into the palace to escort the Liang ruler to a separate palace; Ke pushed open the door, saw the king, kowtowed and apologized, \"Ke's person once served the Xiao house—today I cannot bear to see this.", idiomatic: "The Chen king sent masters of writing attendant Liu Shizhi to lead fierce-proclamation general Shen Ke with troops into the palace to escort the Liang ruler to a separate palace; Ke pushed open the door, saw the king, kowtowed and said, \"I once served the house of Xiao—today I cannot bear to see this." },
  { zh: "分受死耳，決不奉命！", literal: "I would rather accept death—I will never obey the order!", idiomatic: "I would rather accept death—I will never obey the order!" },
  { zh: "」王嘉其意，不復逼，更以蕩主王僧志代之。", literal: "\" The king praised his intent, pressed no further, and replaced him with tent guard Wang Sengzhi.", idiomatic: "\" The king praised his intent, pressed no further, and replaced him with tent guard Wang Sengzhi." },
  { zh: "乙亥，王即皇帝位於南郊，還宮，大赦，改元。", literal: "On yihai, the king took the imperial throne at the southern suburb, returned to the palace, proclaimed a general amnesty, and changed the era name.", idiomatic: "On yihai, the king took the imperial throne at the southern suburb, returned to the palace, proclaimed a general amnesty, and changed the era name." },
  { zh: "奉梁敬帝為江陰王，梁太后為太妃，皇后為妃。", literal: "He honored Liang Emperor Jing as Prince of Jiangyin, the Liang empress dowager as grand consort, and the empress as consort.", idiomatic: "He honored Emperor Jing of Liang as Prince of Jiangyin, the Liang empress dowager as grand consort, and the empress as consort." },
  { zh: "以給事黃門侍郎蔡景歷為秘書監、中書通事舍人。", literal: "Palace Attendant of the Masters of Writing Cai Jingli was made Director of the Secretariat and Masters of Writing Communicator Attendant.", idiomatic: "Palace attendant of the masters of writing Cai Jingli was made director of the secretariat and masters of writing communicator attendant." },
  { zh: "是時政事皆由中書省，置二十一局，各當尚書諸曹，總國機要，尚書唯聽受而已。", literal: "At that time all government affairs passed through the Masters of Writing Office; twenty-one bureaus were established, each matching the various departments of the Masters of Writing, overseeing the state's crucial affairs; the Masters of Writing only received and transmitted.", idiomatic: "At that time all government affairs passed through the masters of writing office; twenty-one bureaus were established, each matching the various departments, overseeing the state's crucial affairs; the masters of writing only received and transmitted." },
  { zh: "丙子，上幸鐘山，祠蔣帝廟。", literal: "On bingzi, the emperor visited Zhongshan and sacrificed at the temple of Emperor Jiang.", idiomatic: "On bingzi, the emperor visited Zhongshan and sacrificed at the temple of Emperor Jiang." },
  { zh: "庚辰，上出佛牙於杜姥宅，設無遮大會，帝親出闕前膜拜。", literal: "On gengchen, the emperor brought out the Buddha's tooth at Old Lady Du's residence and held an unbounded great assembly; the emperor personally went out before the gate and performed obeisance.", idiomatic: "On gengchen, the emperor brought out the Buddha's tooth at Old Lady Du's residence and held an unbounded great assembly; the emperor personally went out before the gate and performed obeisance." },
  { zh: "辛巳，追尊皇考文贊為景皇帝，廟號太祖，皇妣董氏曰安皇后，追立前夫人錢氏為昭皇后，世子克為孝懷太子，立夫人章氏為皇后。", literal: "On xinsi, he posthumously honored his deceased father Wenzan as Emperor Jing, temple name Taizu; his mother Lady Dong as Empress An; established his former wife Lady Qian as Empress Zhao; his heir Ke as Filial and Cherishing Crown Prince; and installed Lady Zhang as empress.", idiomatic: "On xinsi, he posthumously honored his deceased father Wenzan as Emperor Jing, temple name Taizu; his mother Lady Dong as Empress An; established his former wife Lady Qian as Empress Zhao; his heir Ke as filial and cherishing crown prince; and installed Lady Zhang as empress." },
  { zh: "章後，烏程人也。", literal: "Empress Zhang was a native of Wucheng.", idiomatic: "Empress Zhang was a native of Wucheng." },
  { zh: "置刪定郎，治律令。", literal: "Revising clerks were established to work on statutes and ordinances.", idiomatic: "Revising clerks were established to work on statutes and ordinances." },
  { zh: "乙酉，周王祀圜丘；", literal: "On yiyou, the Zhou king sacrificed at the Round Mound;", idiomatic: "On yiyou, the Northern Zhou king sacrificed at the Round Mound;" },
  { zh: "丙戌，祀方丘；", literal: "on bingxu he sacrificed at the Square Mound;", idiomatic: "on bingxu he sacrificed at the Square Mound;" },
  { zh: "甲午，祭太社。", literal: "on jiawu he sacrificed to the Great Altar of Soil and Grain.", idiomatic: "on jiawu he sacrificed to the Great Altar of Soil and Grain." },
  { zh: "戊子，太祖神主祔太廟，七廟始共用一太牢，始祖薦首，餘皆骨體。", literal: "On wuzi, the Grand Ancestor's spirit tablet was placed in the Imperial Ancestral Temple; the seven temples for the first time shared one grand victim; the founding ancestor was offered the head, the rest all bone and flesh.", idiomatic: "On wuzi, the Grand Ancestor's spirit tablet was placed in the Imperial Ancestral Temple; the seven temples for the first time shared one grand victim; the founding ancestor was offered the head, the rest all bone and flesh." },
  { zh: "侯安都至武昌，王琳將樊猛棄城走，周文育自豫章會之。", literal: "Hou Andu reached Wuchang; Wang Lin's general Fan Meng abandoned the city and fled; Zhou Wenyu joined him from Yuzhang.", idiomatic: "Hou Andu reached Wuchang; Wang Lin's general Fan Meng abandoned the city and fled; Zhou Wenyu joined him from Yuzhang." },
  { zh: "安都聞上受禪，歎曰：「吾今茲必敗，戰無名矣！", literal: "Andu heard the emperor had received the Mandate and sighed, \"I am sure to be defeated this time—the battle has no name!", idiomatic: "Andu heard the emperor had received the Mandate and sighed, \"I am sure to be defeated this time—the battle has no name!" },
  { zh: "」時兩將俱行，不相統攝，部下交爭，稍不相平。", literal: "\" At that time both generals marched together without unified command; their subordinates quarreled and gradually were not at peace.", idiomatic: "\" At that time both generals marched together without unified command; their subordinates quarreled and grew increasingly at odds." },
  { zh: "軍至郢州，琳將潘純陀於城中遙射官軍，安都怒，進軍圍之；", literal: "When the army reached Yingzhou, Wang Lin's general Pan Chunduo shot at the government army from afar in the city; Andu was angry and advanced to besiege it;", idiomatic: "When the army reached Yingzhou, Wang Lin's general Pan Chunduo shot at the government army from afar in the city; Andu was furious and advanced to besiege it;" },
  { zh: "未克，而王琳至苻口，安都乃釋郢州，悉眾詣沌口，留沈泰一軍守漢曲。", literal: "before it was taken Wang Lin reached Fukou; Andu then released Yingzhou, led the whole force to Zhunkou, and left one army under Shen Tai to guard Hanqu.", idiomatic: "before it fell Wang Lin reached Fukou; Andu then lifted the siege of Yingzhou, led the whole force to Zhunkou, and left one army under Shen Tai to guard Hanqu." },
  { zh: "安都遇風不得進，琳據東岸，安都等據西岸，相持數日，乃合戰，安都等大敗。", literal: "Andu met wind and could not advance; Lin held the eastern bank and Andu and the rest the western bank; they faced one another several days, then joined battle, and Andu and the rest were greatly defeated.", idiomatic: "Andu met contrary wind and could not advance; Lin held the eastern bank and Andu the western; they faced one another several days, then joined battle, and Andu was routed." },
  { zh: "安都、文育及裨將徐敬成、周鐵虎、程靈洗皆為琳所擒，沈泰引兵奔歸。", literal: "Andu, Wenyu, and subordinate generals Xu Jingcheng, Zhou Tiehu, and Cheng Lingxi were all captured by Lin; Shen Tai led the army in flight back.", idiomatic: "Andu, Wenyu, and subordinate generals Xu Jingcheng, Zhou Tiehu, and Cheng Lingxi were all captured by Wang Lin; Shen Tai led the army in flight back." },
  { zh: "琳引見諸將與語，周鐵虎辭氣不屈，琳殺鐵虎而囚安都等，總以一長鎖系之，置琳所坐□□下，令所親宦者王子晉掌視之。", literal: "Lin summoned the generals to meet and speak with them; Zhou Tiehu's words and bearing would not bend; Lin killed Tiehu and imprisoned Andu and the rest, all bound with one long chain, placed beneath the seat where Lin sat □□, and ordered his close eunuch Wang Zijin to oversee them.", idiomatic: "Lin summoned the generals to speak with them; Zhou Tiehu would not bend; Lin killed Tiehu and imprisoned Andu and the rest, all bound with one long chain beneath Lin's seat □□, and ordered his close eunuch Wang Zijin to oversee them." },
  { zh: "琳乃移湘州軍府就郢城，又遣其將樊猛襲據江州。", literal: "Lin then moved the Xiangzhou military headquarters to Ying city and also sent his general Fan Meng in a surprise raid to seize Jiangzhou.", idiomatic: "Lin then moved the Xiangzhou military headquarters to Ying city and also sent his general Fan Meng in a surprise raid to seize Jiangzhou." },
  { zh: "十一月，丙申，上立兄子茜為臨川王，頊為始興王；", literal: "In the eleventh month, on bingshen, the emperor installed his elder brother's son Qian as Prince of Linchuan and Xu as Prince of Shixing;", idiomatic: "In the eleventh month, on bingshen, the emperor installed his elder brother's son Chen Qian as Prince of Linchuan and Chen Xu as Prince of Shixing;" },
  { zh: "弟子曇朗已死，而上未知，遙立為南康王。", literal: "his younger brother's son Tanlang was already dead, but the emperor did not know and installed him from afar as Prince of Nankang.", idiomatic: "his nephew Tanlang was already dead, but the emperor did not know and installed him from afar as Prince of Nankang." },
  { zh: "庚子，周王享太廟；", literal: "On gengzi, the Zhou king offered at the Imperial Ancestral Temple;", idiomatic: "On gengzi, the Northern Zhou king offered at the Imperial Ancestral Temple;" },
  { zh: "丁未，祀圜丘；", literal: "on dingwei he sacrificed at the Round Mound;", idiomatic: "on dingwei he sacrificed at the Round Mound;" },
  { zh: "十二月，庚午，謁成陵；", literal: "In the twelfth month, on gengwu, he visited Cheng Mausoleum;", idiomatic: "In the twelfth month, on gengwu, he visited Cheng Mausoleum;" },
  { zh: "癸酉，還宮。", literal: "on guiyou he returned to the palace.", idiomatic: "on guiyou he returned to the palace." },
  { zh: "譙淹帥水軍七千、老弱三萬自蜀江東下，欲就王琳，周使開府儀同三司賀若敦、叱羅暉等擊之，斬淹，悉俘其眾。", literal: "Qiao Yan led seven thousand of the navy and thirty thousand old and weak down the eastern Yangzi from Shu, wishing to join Wang Lin; Zhou sent Acting Three Excellencies He Ruo Dun, Chiluo Hui, and others to strike him, beheaded Yan, and captured all his masses.", idiomatic: "Qiao Yan led seven thousand of the navy and thirty thousand old and weak down the eastern Yangzi from Shu, wishing to join Wang Lin; Northern Zhou sent He Ruo Dun and Chiluo Hui, equal in honor to the three dukes, to strike him, beheaded Yan, and captured all his forces." },
  { zh: "是歲，詔給事黃門侍郎蕭乾招諭閩中。", literal: "That year, an edict ordered Palace Attendant of the Masters of Writing Xiao Qian to summon and instruct Minzhong.", idiomatic: "That year, an edict ordered palace attendant of the masters of writing Xiao Qian to summon and instruct Minzhong." },
  { zh: "時熊曇朗在豫章，周迪在臨川，留異在東陽，陳寶應在晉安，共相連結，閩中豪帥往往立砦以自保。", literal: "At that time Xiong Tanlang was in Yuzhang, Zhou Di in Linchuan, Liu Yi in Dongyang, and Chen Baoying in Jin'an, all linked together; Minzhong strongmen often built forts to protect themselves.", idiomatic: "At that time Xiong Tanlang was in Yuzhang, Zhou Di in Linchuan, Liu Yi in Dongyang, and Chen Baoying in Jin'an, all linked together; Minzhong strongmen often built forts to protect themselves." },
  { zh: "上患之，使乾諭以禍福，豪帥皆帥眾請降，即以乾為建安太守。", literal: "The emperor was troubled by this and sent Qian to instruct them with fortune and disaster; the strongmen all led the masses to beg surrender, and Qian was immediately made Administrator of Jian'an.", idiomatic: "The emperor was troubled by this and sent Qian to instruct them with fortune and disaster; the strongmen all led their followers to surrender, and Qian was immediately made administrator of Jian'an." },
  { zh: "乾，子范之子也。", literal: "Qian was a son of Zifan.", idiomatic: "Qian was a son of Zifan." },
  { zh: "初，梁興州刺史席固以州降魏，周太祖以固為豐州刺史。", literal: "Earlier, Liang Xingzhou Inspector Xi Gu surrendered the province to Wei; Zhou's Grand Ancestor made Gu Fengzhou inspector.", idiomatic: "Earlier, Liang Xingzhou inspector Xi Gu surrendered the province to Wei; Northern Zhou's Grand Ancestor made Gu Fengzhou inspector." },
  { zh: "久之，固猶習梁法，不遵北方制度，周人密欲代之，而難其人，乃以司憲中大夫令狐整權鎮豐州，委以代固之略。", literal: "After a long while Gu still followed Liang ways and did not observe northern regulations; Zhou men secretly wished to replace him but found no man for it; they therefore made Chief Rectifier of the Law Linghu Zheng provisional garrison commander of Fengzhou and entrusted him with the plan to replace Gu.", idiomatic: "After a long while Gu still followed Liang ways and did not observe northern regulations; Northern Zhou secretly wished to replace him but found no suitable man; they therefore made chief rectifier Linghu Zheng provisional garrison commander of Fengzhou and entrusted him with the plan to replace Gu." },
  { zh: "整廣佈恩威，傾射撫接，數月之間，化洽州府。", literal: "Zheng broadly spread favor and awe, poured out care and comfort, and within several months transformation pervaded the province and prefecture.", idiomatic: "Zheng broadly spread favor and awe, poured out care and comfort, and within several months won over the province." },
  { zh: "於是除整豐州刺史，以固為湖州刺史。", literal: "Thereupon Zheng was appointed Fengzhou inspector and Gu made Huzhou inspector.", idiomatic: "Thereupon Zheng was appointed Fengzhou inspector and Gu made Huzhou inspector." },
  { zh: "整遷豐州於武當，旬日之間，城府周備，遷者如歸。", literal: "Zheng moved Fengzhou to Wudang; within ten days walls and offices were complete roundly, and those who moved felt as if returning home.", idiomatic: "Zheng moved Fengzhou to Wudang; within ten days walls and offices were complete, and those who moved felt as if returning home." },
  { zh: "固之去也。", literal: "When Gu departed.", idiomatic: "When Gu departed." },
  { zh: "其部曲多願留為整左右，整諭以朝制，弗許，莫不流涕而去。", literal: "his followers mostly wished to remain as Zheng's attendants; Zheng instructed them in court regulation and would not permit it; none failed to go away weeping.", idiomatic: "his followers mostly wished to remain as Zheng's attendants; Zheng cited court regulation and refused; none failed to leave weeping." },
  { zh: "齊人於長城內築重城，自庫洛枝東至鳴紇戍，凡四百餘里。", literal: "Qi men built a double wall within the Long Wall from Kulozhi east to Minghe Garrison, more than four hundred li in all.", idiomatic: "Northern Qi built a double wall within the Long Wall from Kulozhi east to Minghe Garrison, more than four hundred li in all." },
  { zh: "初，齊有術士言「亡高者黑衣」，故高祖每出，不欲見沙門。", literal: "Earlier, Qi had a technician who said, \"He who ends Gao wears black,\" so the Grand Ancestor each time he went out did not wish to see Buddhist monks.", idiomatic: "Earlier, Northern Qi had a diviner who said, \"He who ends Gao wears black,\" so Gao Huan each time he went out did not wish to see Buddhist monks." },
  { zh: "顯祖在晉陽，問左右：「何物最黑？", literal: "Manifest Ancestor was at Jinyang and asked those at his side, \"What thing is blackest?", idiomatic: "Gao Yang was at Jinyang and asked those at his side, \"What thing is blackest?" },
  { zh: "」對曰：「無過於漆。", literal: "\" They answered, \"Nothing surpasses lacquer.", idiomatic: "\" They answered, \"Nothing surpasses lacquer." },
  { zh: "」帝以上黨王渙于兄弟第七，使庫直都督破六韓伯升之鄴征渙。", literal: "\" The emperor, because Prince Huan of Shangdang was seventh among the brothers, sent depot-director commander Poluohan Bosheng to Ye to campaign against Huan.", idiomatic: "\" The emperor, because Prince Huan of Shangdang was seventh among the brothers, sent depot-director commander Poluohan Bosheng to Ye against Huan." },
  { zh: "渙至紫陌橋，殺伯升而逃，浮河南渡；", literal: "Huan reached Zimo Bridge, killed Bosheng and fled, crossed the Yellow River floating south;", idiomatic: "Huan reached Zimo Bridge, killed Bosheng and fled, and crossed the Yellow River floating south;" },
  { zh: "至濟州，為人所執，送鄴。", literal: "At Jizhou he was seized by men and sent to Ye.", idiomatic: "At Jizhou he was seized and sent to Ye." },
  { zh: "帝之為太原公也，與永安王浚偕見世宗，帝有時洟出，浚責帝左右曰：「何不為二兄拭鼻！", literal: "When the emperor had been Duke of Taiyuan, he and Prince Jun of Yong'an had visited Emperor Shizong together; the emperor once let mucus run; Jun rebuked the emperor's attendants, saying, \"Why do you not wipe Second Brother's nose for him!", idiomatic: "When the emperor had been Duke of Taiyuan, he and Prince Jun of Yong'an had visited Emperor Shizong together; the emperor once let mucus run; Jun rebuked the emperor's attendants, saying, \"Why do you not wipe Second Brother's nose for him!" },
  { zh: "」帝心銜之。", literal: "\" The emperor bore a grudge in his heart.", idiomatic: "\" The emperor bore a grudge in his heart." },
  { zh: "及即位，浚為青州刺史，聰明矜恕，吏民悅之。", literal: "When he took the throne, Jun was Qingzhou inspector—clever, strict yet forgiving; officials and people were pleased with him.", idiomatic: "When he took the throne, Jun was Qingzhou inspector—clever, strict yet forgiving; officials and people were pleased with him." },
  { zh: "浚以帝嗜酒，私謂親近曰：「二兄因酒敗德，朝臣無敢諫者。", literal: "Jun, because the emperor loved wine, said privately to those close to him, \"Second Brother ruins his virtue through wine, yet no court minister dares remonstrate.", idiomatic: "Jun, because the emperor loved wine, said privately to those close to him, \"Second Brother ruins his virtue through wine, yet no court minister dares remonstrate." },
  { zh: "大敵未滅，吾甚以為憂。", literal: "The great enemy is not yet destroyed—I am deeply troubled.", idiomatic: "The great enemy is not yet destroyed—I am deeply troubled." },
  { zh: "欲乘驛至鄴面諫，不知用吾不？", literal: "I wish to take the post road to Ye and remonstrate face to face—will my counsel be used?", idiomatic: "I wish to take the post road to Ye and remonstrate face to face—will my counsel be used?" },
  { zh: "」或密以白帝，帝益銜之。", literal: "\" Someone secretly reported this to the emperor, and he bore an even deeper grudge.", idiomatic: "\" Someone secretly reported this to the emperor, and he bore an even deeper grudge." },
  { zh: "浚入朝，從幸東山，帝裸裎為樂。", literal: "Jun came to court and followed the emperor on an excursion to Eastern Hill; the emperor disported naked for amusement.", idiomatic: "Jun came to court and followed the emperor on an excursion to Eastern Hill; the emperor disported naked for amusement." },
  { zh: "浚進諫曰：「此非人主所宜！", literal: "Jun advanced to remonstrate, saying, \"This is not fitting for a sovereign!", idiomatic: "Jun advanced to remonstrate, saying, \"This is not fitting for a sovereign!" },
  { zh: "」帝不悅。", literal: "\" The emperor was displeased.", idiomatic: "\" The emperor was displeased." },
  { zh: "浚又於屏處召楊愔，譏其不諫。", literal: "Jun again summoned Yang Yin in a screened place and reproached him for not remonstrating.", idiomatic: "Jun again summoned Yang Yin in a screened place and reproached him for not remonstrating." },
  { zh: "帝時不欲大臣與諸王交通，愔懼，奏之。", literal: "The emperor at that time did not wish great ministers to associate with princes; Yin feared this and memorialized it.", idiomatic: "The emperor at that time did not wish great ministers to associate with princes; Yin feared this and memorialized it." },
  { zh: "帝大怒曰：「小人由來難忍！", literal: "The emperor was greatly angered and said, \"Petty men have always been hard to bear!", idiomatic: "The emperor was greatly angered and said, \"Petty men have always been hard to bear!" },
  { zh: "」遂罷酒，還宮。", literal: "\" He thereupon ended the wine and returned to the palace.", idiomatic: "\" He thereupon ended the wine and returned to the palace." },
  { zh: "浚尋還州，又上書切諫，詔征浚。", literal: "Before long Jun returned to his province and again sent a memorial with stern remonstrance; an edict summoned Jun.", idiomatic: "Before long Jun returned to his province and again sent a memorial with stern remonstrance; an edict summoned Jun." },
  { zh: "浚懼禍，謝疾不至，帝遣馳驛收浚，老幼泣送者數千人，至鄴，與上黨王渙皆盛以鐵籠，置於北城地牢，飲食溲穢，共在一所。", literal: "Jun feared disaster, pleaded illness, and did not come; the emperor sent post riders to seize him; old and young weeping as they sent him off numbered several thousand; at Ye he and Prince Huan of Shangdang were both packed in iron cages, placed in the north-city dungeon, food and drink mixed with filth, together in one cell.", idiomatic: "Jun feared disaster, pleaded illness, and did not come; the emperor sent post riders to seize him; old and young weeping as they sent him off numbered several thousand; at Ye he and Prince Huan of Shangdang were both packed in iron cages, placed in the north-city dungeon, food and drink mixed with filth, together in one cell." },
  { zh: "春，正月，王琳引兵下，至湓城，屯於白水浦，帶甲十萬。", literal: "Spring, first month: Wang Lin led troops downstream to Pencheng and encamped at Baishui Ford with one hundred thousand armored men.", idiomatic: "Spring, first month: Wang Lin led troops downstream to Pencheng and encamped at Baishui Ford with one hundred thousand armored men." },
  { zh: "琳以北江州刺史魯悉達為鎮北將軍，上亦以悉達為征西將軍，各送鼓吹女樂。", literal: "Lin made Northern Jiangzhou Inspector Lu Sidá General Who Pacifies the North; the emperor also made Sidá General Who Campaigns West and each sent him martial music and female performers.", idiomatic: "Lin made Northern Jiangzhou inspector Lu Sidá general who pacifies the north; the emperor also made Sidá general who campaigns west and each sent him martial music and female performers." },
  { zh: "悉達兩受之，遷延顧望，皆不就；", literal: "Sidá accepted from both sides, delayed and looked about, and attached himself to neither;", idiomatic: "Sidá accepted from both sides, delayed and looked about, and attached himself to neither;" },
  { zh: "上遣安西將軍沈泰襲之，不克。", literal: "the emperor sent General Who Pacifies the West Shen Tai to raid him but did not overcome him.", idiomatic: "the emperor sent general who pacifies the west Shen Tai to raid him but did not overcome him." },
  { zh: "琳欲引軍東下，而悉達制其中流，琳遣使說誘，終不從。", literal: "Lin wished to lead his army east downstream, but Sidá controlled the midstream; Lin sent envoys to persuade and entice him, yet in the end he would not follow.", idiomatic: "Lin wished to lead his army east downstream, but Sidá controlled the midstream; Lin sent envoys to persuade and entice him, yet in the end he would not follow." },
  { zh: "己亥，琳遣記室宗虩求援於齊，且請納梁永嘉王莊以主梁祀。", literal: "On jihai, Lin sent recorder Zong Xi to seek aid from Qi and also asked to install Prince Zhuang of Yongjia of Liang to preside over Liang sacrifices.", idiomatic: "On jihai, Lin sent recorder Zong Xi to seek aid from Qi and also asked to install Prince Zhuang of Yongjia of Liang to preside over Liang sacrifices." },
  { zh: "衡州刺史周迪欲自據南川，乃總召所部八郡守宰結盟，齊言入赴。", literal: "Hengzhou Inspector Zhou Di wished to hold the southern rivers himself; he therefore gathered the magistrates of eight commanderies under him to form an alliance, all speaking of marching to answer the call.", idiomatic: "Hengzhou inspector Zhou Di wished to hold the southern rivers himself; he therefore gathered the magistrates of eight commanderies under him to form an alliance, all speaking of marching to answer the call." },
  { zh: "上恐其為變，厚慰撫之。", literal: "The emperor feared he would turn rebel and comforted and reassured him generously.", idiomatic: "The emperor feared he would turn rebel and comforted and reassured him generously." },
  { zh: "新吳洞主余孝頃遣沙門道林說琳曰：「周迪、黃法□皆依附金陵，陰窺間隙，大軍若下，必為後患；", literal: "Xinwu cave lord Yu Xiaoxiang sent the monk Daolin to persuade Lin, saying, \"Zhou Di and Huang Fa□ have both attached themselves to Jinling and secretly watch for openings; if the great army goes downstream, they will surely become a trouble in the rear;", idiomatic: "Xinwu cave lord Yu Xiaoxiang sent the monk Daolin to persuade Lin, saying, \"Zhou Di and Huang Fa□ have both attached themselves to Jinling and secretly watch for openings; if the great army goes downstream, they will surely become a trouble in the rear;" },
  { zh: "不如先定南川，然後東下，孝頃請席捲所部以從下吏。", literal: "better first secure the southern rivers, then go east downstream—Xiaoxiang asks to sweep up his following and serve under your command.", idiomatic: "better first secure the southern rivers, then go east downstream—Xiaoxiang asks to sweep up his following and serve under your command." },
  { zh: "」琳乃遣輕車將軍樊猛、平南將軍李孝欽、平東將軍劉廣德將兵八千赴之，使孝頃總督三將，屯於臨川故郡，徵兵糧於迪，以觀其所為。", literal: "\" Lin thereupon sent Light Chariot General Fan Meng, General Who Pacifies the South Li Xiaoqin, and General Who Pacifies the East Liu Guangde to lead eight thousand troops thither, made Xiaoxiang overall commander of the three generals, encamped at the old seat of Linchuan commandery, and levied troops and grain from Di to observe what he would do.", idiomatic: "\" Lin thereupon sent light chariot general Fan Meng, general who pacifies the south Li Xiaoqin, and general who pacifies the east Liu Guangde to lead eight thousand troops thither, made Xiaoxiang overall commander of the three generals, encamped at the old seat of Linchuan commandery, and levied troops and grain from Di to observe what he would do." },
  { zh: "以開府儀同三司侯瑱為司空，衡州刺史歐陽頠為都督交、廣等十九州諸軍事、廣州刺史。", literal: "Palace Attendant of the Third Rank Hou Tian was made Minister of Works; Hengzhou Inspector Ouyang Yi was made Commander over Military Affairs of nineteen provinces including Jiao and Guang, and Inspector of Guangzhou.", idiomatic: "Palace attendant of the third rank Hou Tian was made minister of works; Hengzhou inspector Ouyang Yi was made commander over military affairs of nineteen provinces including Jiao and Guang, and inspector of Guangzhou." },
  { zh: "周以晉公護為太師。", literal: "Zhou made Duke of Jin Yuwen Hu Grand Preceptor.", idiomatic: "Northern Zhou made Duke of Jin Yuwen Hu grand preceptor." },
  { zh: "辛丑，上祀南郊，大赦；", literal: "On xinchou, the emperor sacrificed at the southern suburb and proclaimed a general amnesty;", idiomatic: "On xinchou, the emperor sacrificed at the southern suburb and proclaimed a general amnesty;" },
  { zh: "乙巳，祀北郊。", literal: "on yisi, at the northern suburb.", idiomatic: "on yisi, at the northern suburb." },
  { zh: "辛亥，周王耕藉田。", literal: "On xinhai, the Zhou king plowed the sacred field.", idiomatic: "On xinhai, the Zhou king plowed the sacred field." },
  { zh: "癸丑，周立王后獨孤氏。", literal: "On guichou, Zhou established Lady Dugu as queen.", idiomatic: "On guichou, Northern Zhou established Lady Dugu as queen." },
  { zh: "戊午，上禮明堂。", literal: "On wuwu, the emperor performed rites at the Bright Hall.", idiomatic: "On wuwu, the emperor performed rites at the Bright Hall." },
  { zh: "二月，壬申，南豫州刺史沈泰奔齊。", literal: "Second month, on renshen, Southern Yuzhou Inspector Shen Tai fled to Qi.", idiomatic: "Second month, on renshen, Southern Yuzhou inspector Shen Tai fled to Qi." },
  { zh: "齊北豫州刺史司馬消難，以齊主昏虐滋甚，陰為自全之計，曲意撫循所部。", literal: "Qi Northern Yuzhou Inspector Sima Xiaonan, because the Qi ruler grew ever more muddled and cruel, secretly made plans for his own preservation and bent his will to comfort and shepherd his command.", idiomatic: "Qi Northern Yuzhou inspector Sima Xiaonan, because the Qi ruler grew ever more muddled and cruel, secretly made plans for his own preservation and bent his will to comfort and shepherd his command." },
  { zh: "消難尚高祖女，情好不睦，公主訴之。", literal: "Xiaonan had married a daughter of Gaozu; affection was not harmonious, and the princess complained.", idiomatic: "Xiaonan had married a daughter of Gaozu; affection was not harmonious, and the princess complained." },
  { zh: "上黨王渙之亡也，鄴中大擾，疑其赴成皋。", literal: "When Prince Huan of Shangdang fled, Ye was greatly disturbed, suspecting he had gone to Chenggao.", idiomatic: "When Prince Huan of Shangdang fled, Ye was greatly disturbed, suspecting he had gone to Chenggao." },
  { zh: "消難從弟子瑞為尚書左丞，與御史中丞畢義雲有隙，義雲遣御史張子階詣北豫州采風聞，先禁消難典簽家客等。", literal: "Xiaonan's younger cousin's son Rui was Left Director of the Secretariat and had a rift with Censor-in-Chief Bi Yiyun; Yiyun sent censor Zhang Zijie to Northern Yuzhou to gather rumors, first detaining Xiaonan's chief clerk, household guests, and the like.", idiomatic: "Xiaonan's younger cousin's son Rui was left director of the secretariat and had a rift with censor-in-chief Bi Yiyun; Yiyun sent censor Zhang Zijie to Northern Yuzhou to gather rumors, first detaining Xiaonan's chief clerk, household guests, and the like." },
  { zh: "消難懼，密令所親中兵參軍裴藻托以私假，間行入關，請降於周。", literal: "Xiaonan was afraid and secretly ordered his intimate Central Army Major Pei Zao, under pretense of private leave, to go by hidden routes into the passes and seek surrender to Zhou.", idiomatic: "Xiaonan was afraid and secretly ordered his intimate central army major Pei Zao, under pretense of private leave, to go by hidden routes into the passes and seek surrender to Zhou." },
  { zh: "三月，甲午，周遣柱國達奚武、大將軍楊忠帥騎士五千迎消難，從間道馳入齊境五百里，前後三遣使報消難，皆不報。", literal: "Third month, on jiawu, Zhou sent pillar of state Daxi Wu and Grand General Yang Zhong to lead five thousand horsemen to welcome Xiaonan; by hidden road they galloped five hundred li into Qi territory; three times before and after they sent envoys to report to Xiaonan, and he answered none.", idiomatic: "Third month, on jiawu, Zhou sent pillar of state Daxi Wu and grand general Yang Zhong to lead five thousand horsemen to welcome Xiaonan; by hidden road they galloped five hundred li into Qi territory; three times before and after they sent envoys to report to Xiaonan, and he answered none." },
  { zh: "去虎牢三十里，武疑有變，欲還，忠曰：「有進死，無退生！", literal: "Thirty li from Hulao, Wu suspected a change and wished to return; Zhong said, \"There is death in advancing, none in retreating!", idiomatic: "Thirty li from Hulao, Wu suspected a change and wished to return; Zhong said, \"There is death in advancing, none in retreating!" },
  { zh: "」獨以千騎夜趣城下。", literal: "\" He alone with a thousand horsemen by night rushed to below the walls.", idiomatic: "\" He alone with a thousand horsemen by night rushed to below the walls." },
  { zh: "城四面峭絕，但聞擊柝聲。", literal: "The walls on four sides were sheer and cut off; only the sound of watch-clappers was heard.", idiomatic: "The walls on four sides were sheer and cut off; only the sound of watch-clappers was heard." },
  { zh: "武親來，麾數百騎西去，忠勒餘騎不動，俟門開而入，馳遣召武。", literal: "Wu came in person and waved several hundred horsemen westward; Zhong held the remaining riders motionless, waited until the gate opened and entered, then galloped to summon Wu.", idiomatic: "Wu came in person and waved several hundred horsemen westward; Zhong held the remaining riders motionless, waited until the gate opened and entered, then galloped to summon Wu." },
  { zh: "齊鎮城伏敬遠勒甲士二千人據東城，舉烽嚴警。", literal: "Qi garrison commander Fu Jingyuan mustered two thousand armored soldiers and held the eastern city, raising beacon fires in strict alarm.", idiomatic: "Qi garrison commander Fu Jingyuan mustered two thousand armored soldiers and held the eastern city, raising beacon fires in strict alarm." },
  { zh: "武憚之，不欲保城，乃多取財物，以消難及其屬先歸，忠以三千騎為殿。", literal: "Wu feared this and did not wish to hold the city; he therefore took much wealth and property, sent Xiaonan and his followers back first, and Zhong with three thousand horsemen brought up the rear.", idiomatic: "Wu feared this and did not wish to hold the city; he therefore took much wealth and property, sent Xiaonan and his followers back first, and Zhong with three thousand horsemen brought up the rear." },
  { zh: "至洛南，皆解鞍而臥。", literal: "South of the Luo, all unslung saddles and lay down.", idiomatic: "South of the Luo, all unslung saddles and lay down." },
  { zh: "齊眾來追，至洛北，忠謂將士曰：「但飽食，今在死地，賊必不敢渡水！", literal: "Qi masses came in pursuit; north of the Luo, Zhong told officers and soldiers, \"Only eat your fill—now we are on dead ground; the bandits will surely not dare cross the water!", idiomatic: "Qi masses came in pursuit; north of the Luo, Zhong told officers and soldiers, \"Only eat your fill—now we are on dead ground; the bandits will surely not dare cross the water!" },
  { zh: "」已而果然，乃徐引還。", literal: "\" And so it proved; they then slowly led the withdrawal.", idiomatic: "\" And so it proved; they then slowly led the withdrawal." },
  { zh: "武歎曰：「達奚武自謂天下健兒，今日服矣！", literal: "Wu sighed and said, \"Daxi Wu took himself for the world's toughest man—today I am humbled!", idiomatic: "Wu sighed and said, \"Daxi Wu took himself for the world's toughest man—today I am humbled!" },
  { zh: "」周以消難為小司徒。", literal: "\" Zhou made Xiaonan Lesser Minister of Education.", idiomatic: "\" Zhou made Xiaonan lesser minister of education." },
  { zh: "丁酉，齊主自晉陽還鄴。", literal: "On dingyou, the Qi ruler returned from Jinyang to Ye.", idiomatic: "On dingyou, the Qi ruler returned from Jinyang to Ye." },
  { zh: "齊發兵援送梁永嘉王莊於江南，冊拜王琳為梁丞相、都督中外諸軍、錄尚書事。", literal: "Qi sent troops to escort Prince Zhuang of Yongjia of Liang to Jiangnan and enfeoffed Wang Lin as Liang chancellor, Commander of All Forces Inside and Outside, and Recorder of the Secretariat.", idiomatic: "Qi sent troops to escort Prince Zhuang of Yongjia of Liang to Jiangnan and enfeoffed Wang Lin as Liang chancellor, commander of all forces inside and outside, and recorder of the secretariat." },
  { zh: "琳遣兄子叔寶帥所部十州刺史子弟赴鄴。", literal: "Lin sent his elder brother's son Shubao to lead the sons and younger brothers of the inspectors of ten provinces under him to Ye.", idiomatic: "Lin sent his elder brother's son Shubao to lead the sons and younger brothers of the inspectors of ten provinces under him to Ye." },
  { zh: "琳奉莊即皇帝位，改元天啟。", literal: "Lin installed Zhuang as emperor, changing the era name to Tianqi.", idiomatic: "Lin installed Zhuang as emperor, changing the era name to Tianqi." },
  { zh: "追謚建安公淵明曰閔皇帝。", literal: "Posthumous title for Duke Yuanming of Jian'an was set as Emperor Min.", idiomatic: "Posthumous title for Duke Yuanming of Jian'an was set as Emperor Min." },
  { zh: "莊以琳為侍中、大將軍、中書監，餘依齊朝之命。", literal: "Zhuang made Lin Palace Attendant, Grand General, and Director of the Secretariat; the rest followed Qi court orders.", idiomatic: "Zhuang made Lin palace attendant, grand general, and director of the secretariat; the rest followed Qi court orders." },
  { zh: "夏，四月，甲子，上享太廟。", literal: "Summer, fourth month, on jiazi, the emperor offered at the imperial temple.", idiomatic: "Summer, fourth month, on jiazi, the emperor offered at the imperial temple." },
  { zh: "乙丑，上使人害梁敬帝，立梁武林侯諮之子季卿為江陰王。", literal: "On yichou, the emperor had men kill the Emperor Jing of Liang and set up Jiji, son of Marquis Zi of Wulin, as King of Jiangyin.", idiomatic: "On yichou, the emperor had men kill Emperor Jing of Liang and set up Jiji, son of Marquis Zi of Wulin, as king of Jiangyin." },
  { zh: "己巳，周以太師護為雍州牧。", literal: "On jisi, Zhou made Grand Preceptor Hu Governor of Yongzhou.", idiomatic: "On jisi, Northern Zhou made grand preceptor Hu governor of Yongzhou." },
  { zh: "甲戌，周王后獨孤氏殂。", literal: "On jiaxu, Zhou Queen Lady Dugu died.", idiomatic: "On jiaxu, Northern Zhou queen Lady Dugu died." },
  { zh: "辛巳，齊大赦。", literal: "On xinsi, Qi proclaimed a general amnesty.", idiomatic: "On xinsi, Qi proclaimed a general amnesty." },
  { zh: "齊主以旱祈雨於西門豹祠，不應，毀之，並掘其塚。", literal: "The Qi ruler prayed for rain at the shrine of Lord Bao of Ximen because of drought; there was no response; he destroyed it and also dug up the tomb.", idiomatic: "The Qi ruler prayed for rain at the shrine of Lord Bao of Ximen because of drought; there was no response; he destroyed it and also dug up the tomb." },
  { zh: "五月，癸巳，余孝頃等且二萬軍於工塘，連八城以逼周迪。", literal: "Fifth month, on guisi, Yu Xiaoxiang and others with nearly twenty thousand encamped at Gongtang, linking eight forts to press Zhou Di.", idiomatic: "Fifth month, on guisi, Yu Xiaoxiang and others with nearly twenty thousand encamped at Gongtang, linking eight forts to press Zhou Di." },
  { zh: "迪懼，請和，並送兵糧。", literal: "Di was afraid, sought peace, and also sent troops and grain.", idiomatic: "Di was afraid, sought peace, and also sent troops and grain." },
  { zh: "樊猛等欲受盟而還；", literal: "Fan Meng and the rest wished to accept the alliance and return;", idiomatic: "Fan Meng and the rest wished to accept the alliance and return;" },
  { zh: "孝頃貪其利，不許，樹柵圍之。", literal: "Xiaoxiang coveted the profit and would not permit it; he built palisades and besieged him.", idiomatic: "Xiaoxiang coveted the profit and would not permit it; he built palisades and besieged him." },
  { zh: "由是猛等與孝頃不協。", literal: "Thereupon Meng and the rest were at odds with Xiaoxiang.", idiomatic: "Thereupon Meng and the rest were at odds with Xiaoxiang." },
  { zh: "周以大司空侯莫陳崇為大宗伯。", literal: "Zhou made Grand Minister of Works Houmochen Chong Grand Director of the Masses.", idiomatic: "Northern Zhou made grand minister of works Houmochen Chong grand director of the masses." },
  { zh: "癸丑，齊廣陵南城主張顯和、長史張僧那各帥所部來降。", literal: "On guichou, Qi Guangling south-city chief Zhang Xianhe and chief clerk Zhang Sengna each led their followers to surrender.", idiomatic: "On guichou, Qi Guangling south-city chief Zhang Xianhe and chief clerk Zhang Sengna each led their followers to surrender." },
  { zh: "辛酉，齊以尚書令長廣王湛錄尚書事，驃騎大將軍平秦王歸彥為尚書左僕射。", literal: "On xinyou, Qi made Secretariat Director Prince Zhan of Changgung Recorder of the Secretariat and Flying Cavalry Grand General Prince Guiyan of Pingqin Left Vice Director of the Secretariat.", idiomatic: "On xinyou, Qi made secretariat director Prince Zhan of Changgung recorder of the secretariat and flying cavalry grand general Prince Guiyan of Pingqin left vice director of the secretariat." },
  { zh: "甲辰，以前左僕射楊愔為尚書令。", literal: "On jiachen, former Left Vice Director Yang Yin was made Secretariat Director.", idiomatic: "On jiachen, former left vice director Yang Yin was made secretariat director." },
  { zh: "辛酉，上幸大莊嚴寺捨身；", literal: "On xinyou, the emperor went to Great Zhuangyan Temple to offer his person;", idiomatic: "On xinyou, the emperor went to Great Zhuangyan Temple to offer his person;" },
  { zh: "壬戌，群臣表請還宮。", literal: "on renxu, the host of ministers memorialized asking him to return to the palace.", idiomatic: "on renxu, the host of ministers memorialized asking him to return to the palace." },
  { zh: "六月，乙丑，齊主北巡，以太子殷監國，因立大都督府與尚書省分理眾務，仍開府置佐。", literal: "Sixth month, on yichou, the Qi ruler toured north; the crown prince Yin oversaw the state; a great field headquarters was established to divide affairs with the Secretariat, and a bureau was opened with assistants.", idiomatic: "Sixth month, on yichou, the Qi ruler toured north; the crown prince Yin oversaw the state; a great field headquarters was established to divide affairs with the secretariat, and a bureau was opened with assistants." },
  { zh: "齊主特崇其選，以趙郡王叡為侍中、攝大都督府長史。", literal: "The Qi ruler especially honored this selection, making Prince Rui of Zhao commandery Palace Attendant and acting chief clerk of the great headquarters.", idiomatic: "The Qi ruler especially honored this selection, making Prince Rui of Zhao commandery palace attendant and acting chief clerk of the great headquarters." },
  { zh: "己巳，詔司空侯瑱與領軍將軍徐度帥舟師為前軍，以討王琳。", literal: "On jisi, an edict ordered Minister of Works Hou Tian and General of the Palace Guard Xu Du to lead the fleet as the vanguard to campaign against Wang Lin.", idiomatic: "On jisi, an edict ordered minister of works Hou Tian and general of the palace guard Xu Du to lead the fleet as the vanguard to campaign against Wang Lin." },
  { zh: "齊主至祁連池；", literal: "The Qi ruler reached Qilian Pool;", idiomatic: "The Qi ruler reached Qilian Pool;" },
  { zh: "戊寅，還晉陽。", literal: "on wuyin, he returned to Jinyang.", idiomatic: "on wuyin, he returned to Jinyang." },
  { zh: "秋，七月，戊戌，上幸石頭，送侯瑱等。", literal: "Autumn, seventh month, on wuxu, the emperor went to Stone City to send off Hou Tian and the rest.", idiomatic: "Autumn, seventh month, on wuxu, the emperor went to Stone City to send off Hou Tian and the rest." },
  { zh: "高州刺史黃法□、吳興太守沈恪、寧州刺史周敷合兵救周迪。", literal: "Gaozhou Inspector Huang Fa□, Wuxing Administrator Shen Ke, and Ningzhou Inspector Zhou Fu united armies to rescue Zhou Di.", idiomatic: "Gaozhou inspector Huang Fa□, Wuxing administrator Shen Ke, and Ningzhou inspector Zhou Fu united armies to rescue Zhou Di." },
  { zh: "敷自臨川故郡斷江口，分兵攻余孝頃別城。", literal: "Fu from the old seat of Linchuan commandery cut the river mouth and divided troops to attack Xiaoxiang's detached forts.", idiomatic: "Fu from the old seat of Linchuan commandery cut the river mouth and divided troops to attack Xiaoxiang's detached forts." },
  { zh: "樊猛等不救而沒；", literal: "Fan Meng and the rest did not rescue them and were destroyed;", idiomatic: "Fan Meng and the rest did not rescue them and were destroyed;" },
  { zh: "劉廣德乘流先下，故獲全。", literal: "Liu Guangde went downstream first by the current and therefore escaped whole.", idiomatic: "Liu Guangde went downstream first by the current and therefore escaped whole." },
  { zh: "孝頃等皆棄舟引兵步走，迪追擊，盡擒之，送孝頃及李孝欽於建康，歸樊猛於王琳。", literal: "Xiaoxiang and the rest all abandoned their boats and led troops away on foot; Di pursued and captured them all, sent Xiaoxiang and Li Xiaoqin to Jiankang, and returned Fan Meng to Wang Lin.", idiomatic: "Xiaoxiang and the rest all abandoned their boats and led troops away on foot; Di pursued and captured them all, sent Xiaoxiang and Li Xiaoqin to Jiankang, and returned Fan Meng to Wang Lin." },
  { zh: "甲辰，上遣吏部尚書謝哲往諭王琳。", literal: "On jiachen, the emperor sent Minister of Personnel Xie Zhe to instruct Wang Lin.", idiomatic: "On jiachen, the emperor sent minister of personnel Xie Zhe to instruct Wang Lin." },
  { zh: "哲，朏之孫也。", literal: "Zhe was grandson of Fei.", idiomatic: "Zhe was grandson of Fei." },
  { zh: "八月，甲子，周大赦。", literal: "Eighth month, on jiazi, Zhou proclaimed a general amnesty.", idiomatic: "Eighth month, on jiazi, Northern Zhou proclaimed a general amnesty." },
  { zh: "乙丑，齊主還鄴。", literal: "On yichou, the Qi ruler returned to Ye.", idiomatic: "On yichou, the Qi ruler returned to Ye." },
  { zh: "辛未，詔臨川王茜西討，以舟師五萬發建康，上幸冶城寺送之。", literal: "On xinwei, an edict ordered Prince Qian of Linchuan on a western campaign; with a fleet of fifty thousand he set out from Jiankang; the emperor went to Yecheng Temple to send him off.", idiomatic: "On xinwei, an edict ordered Prince Qian of Linchuan on a western campaign; with a fleet of fifty thousand he set out from Jiankang; the emperor went to Yecheng Temple to send him off." },
  { zh: "甲戌，齊主如晉陽。", literal: "On jiaxu, the Qi ruler went to Jinyang.", idiomatic: "On jiaxu, the Qi ruler went to Jinyang." },
  { zh: "王琳在白水浦，周文育、侯安都、徐敬成許王子晉以厚賂，子晉乃偽以小船依榻而釣。", literal: "Wang Lin was at Baishui Ford; Zhou Wenyu, Hou Andu, and Xu Jingcheng promised Prince Zijin of Xu rich bribes; Zijin then feigned fishing from a small boat leaning on the couch.", idiomatic: "Wang Lin was at Baishui Ford; Zhou Wenyu, Hou Andu, and Xu Jingcheng promised Prince Zijin of Xu rich bribes; Zijin then feigned fishing from a small boat leaning on the couch." },
  { zh: "夜，載之上岸，入深草中，步投陳軍，還建康自劾。", literal: "By night he ferried them ashore; they entered deep grass, went on foot to join Chen armies, returned to Jiankang, and impeached themselves.", idiomatic: "By night he ferried them ashore; they entered deep grass, went on foot to join Chen armies, returned to Jiankang, and impeached themselves." },
  { zh: "上引見，並宥之，戊寅，復其本官。", literal: "The emperor received them in audience and pardoned them all; on wuyin he restored their former offices.", idiomatic: "The emperor received them in audience and pardoned them all; on wuyin he restored their former offices." },
  { zh: "謝哲返命，王琳請還湘州，詔追眾軍還。", literal: "Xie Zhe returned with his commission; Wang Lin asked to return to Xiangzhou; an edict recalled the mass of armies.", idiomatic: "Xie Zhe returned with his commission; Wang Lin asked to return to Xiangzhou; an edict recalled the mass of armies." },
  { zh: "癸未，眾軍至自大雷。", literal: "On guiwei, the armies arrived from Great Lei.", idiomatic: "On guiwei, the armies arrived from Great Lei." },
  { zh: "九月，甲申，周封少師元羅為韓國公以紹魏後。", literal: "Ninth month, on jiashen, Zhou enfeoffed Lesser Preceptor Yuan Luo as Duke of Han to continue the Wei line.", idiomatic: "Ninth month, on jiashen, Northern Zhou enfeoffed lesser preceptor Yuan Luo as duke of Han to continue the Wei line." },
  { zh: "丁未，周王如同州；", literal: "On dingwei, the Zhou king went to Tongzhou;", idiomatic: "On dingwei, the Zhou king went to Tongzhou;" },
  { zh: "冬，十月，辛酉，還長安。", literal: "Winter, tenth month, on xinyou, he returned to Chang'an.", idiomatic: "Winter, tenth month, on xinyou, he returned to Chang'an." },
  { zh: "余孝頃之弟孝勱及子公揚猶據舊柵不下；", literal: "Yu Xiaoxiang's younger brother Xiaoqin and his son Gongyang still held the old palisade and would not submit;", idiomatic: "Yu Xiaoxiang's younger brother Xiaoqin and his son Gongyang still held the old palisade and would not submit;" },
  { zh: "庚午，詔開府儀同三司周文育都督眾軍出豫章討之。", literal: "on gengwu, an edict ordered Palace Attendant of the Third Rank Zhou Wenyu to command the mass of armies out from Yuzhang to campaign against them.", idiomatic: "on gengwu, an edict ordered palace attendant of the third rank Zhou Wenyu to command the mass of armies out from Yuzhang to campaign against them." },
  { zh: "齊三台成，更命銅爵曰金鳳，金虎曰聖應，冰井曰崇光。", literal: "Qi's Three Terraces were completed; Copper Sparrow was renamed Golden Phoenix, Golden Tiger Holy Response, and Ice Well Splendid Light.", idiomatic: "Qi's Three Terraces were completed; Copper Sparrow was renamed Golden Phoenix, Golden Tiger Holy Response, and Ice Well Splendid Light." },
  { zh: "十一月，甲午，齊主至鄴，大赦。", literal: "Eleventh month, on jiawu, the Qi ruler reached Ye and proclaimed a general amnesty.", idiomatic: "Eleventh month, on jiawu, the Qi ruler reached Ye and proclaimed a general amnesty." },
  { zh: "齊主游三台，戲以槊刺都督尉子輝，應手而斃。", literal: "The Qi ruler roamed the Three Terraces and in sport stabbed Supervisor Wei Zihui with a spear; he fell dead at the blow.", idiomatic: "The Qi ruler roamed the Three Terraces and in sport stabbed supervisor Wei Zihui with a spear; he fell dead at the blow." },
  { zh: "常山王演以帝沈湎，憂憤形於顏色。", literal: "Prince Yan of Changshan, because the emperor was sunk in drink, showed worry and anger in his face.", idiomatic: "Prince Yan of Changshan, because the emperor was sunk in drink, showed worry and anger in his face." },
  { zh: "帝覺之，謂曰：「但令汝在，我何為不縱樂！", literal: "The emperor noticed and said to him, \"So long as you are here, why should I not indulge my pleasures!", idiomatic: "The emperor noticed and said to him, \"So long as you are here, why should I not indulge my pleasures!" },
  { zh: "」演唯啼泣拜伏，竟無所言。", literal: "\" Yan only wept, prostrated himself, and in the end said nothing.", idiomatic: "\" Yan only wept, prostrated himself, and in the end said nothing." },
  { zh: "帝亦大悲，抵杯於地曰：「汝似嫌我如是，自今敢進酒者斬之！", literal: "The emperor also was deeply moved, dashed his cup to the ground, and said, \"You seem to dislike me thus—from today whoever dares bring wine shall be beheaded!", idiomatic: "The emperor also was deeply moved, dashed his cup to the ground, and said, \"You seem to dislike me thus—from today whoever dares bring wine shall be beheaded!" },
  { zh: "」因取所御杯盡壞棄。", literal: "\" He then took all the cups he had used and smashed and discarded them.", idiomatic: "\" He then took all the cups he had used and smashed and discarded them." },
  { zh: "未幾，沉湎益甚，或於諸貴戚家角力批拉，不限貴賤。", literal: "Before long his drowning in drink grew worse; sometimes at the houses of various kin he wrestled and brawled, without distinction of noble or base.", idiomatic: "Before long his drowning in drink grew worse; sometimes at the houses of various kin he wrestled and brawled, without distinction of noble or base." },
  { zh: "唯演至，則內外肅然。", literal: "Only when Yan arrived did inside and outside become solemn.", idiomatic: "Only when Yan arrived did inside and outside become solemn." },
  { zh: "演又密撰事條，將諫，其友王晞以為不可。", literal: "Yan again secretly drafted articles of remonstrance and was about to advise; his friend Wang Xi thought it impossible.", idiomatic: "Yan again secretly drafted articles of remonstrance and was about to advise; his friend Wang Xi thought it impossible." },
  { zh: "演不從，因間極言，遂逢大怒。", literal: "Yan would not follow this; seizing an opening he spoke to the limit and met with great rage.", idiomatic: "Yan would not follow this; seizing an opening he spoke to the limit and met with great rage." },
  { zh: "演性頗嚴，尚書郎中剖斷有失，輒加捶楚，令史奸慝即考竟。", literal: "Yan's nature was rather severe; when Secretariat gentlemen erred in judgment he at once added beating with the staff; clerks who were treacherous and wicked he examined to the end.", idiomatic: "Yan's nature was rather severe; when secretariat gentlemen erred in judgment he at once added beating with the staff; clerks who were treacherous and wicked he examined to the end." },
  { zh: "帝乃立演於前，以刀鐶擬脅，召被演罰者，臨以白刃，求演之短；", literal: "The emperor then stood Yan before him, threatened him with a ring-knife, summoned those Yan had punished, set white blades before them, and sought Yan's faults;", idiomatic: "The emperor then stood Yan before him, threatened him with a ring-knife, summoned those Yan had punished, set white blades before them, and sought Yan's faults;" },
  { zh: "或無所陳，乃釋之。", literal: "when some had nothing to declare, he released him.", idiomatic: "when some had nothing to declare, he released him." },
  { zh: "晞，昕之弟也。", literal: "Xi was younger brother of Xin.", idiomatic: "Xi was younger brother of Xin." },
  { zh: "帝疑演假辭於晞以諫，欲殺之。", literal: "The emperor suspected Yan borrowed Xi's words to remonstrate and wished to kill him.", idiomatic: "The emperor suspected Yan borrowed Xi's words to remonstrate and wished to kill him." },
  { zh: "王私謂晞曰：「王博士，明日當作一條事，為欲相活，亦圖自全，宜深體勿怪。", literal: "The prince said privately to Xi, \"Doctor Wang, tomorrow I must do one thing—to wish to keep you alive and also seek my own preservation; you should understand deeply and not blame me.", idiomatic: "The prince said privately to Xi, \"Doctor Wang, tomorrow I must do one thing—to wish to keep you alive and also seek my own preservation; you should understand deeply and not blame me." },
  { zh: "」乃於眾中杖晞二十。", literal: "\" He then in the assembly beat Xi twenty strokes.", idiomatic: "\" He then in the assembly beat Xi twenty strokes." },
  { zh: "帝尋發怒，聞晞得杖，以故不殺，髡鞭配甲坊。", literal: "The emperor soon grew angry; hearing Xi had been beaten, for that reason he did not kill him but shaved his head, flogged him, and assigned him to the armorers' ward.", idiomatic: "The emperor soon grew angry; hearing Xi had been beaten, for that reason he did not kill him but shaved his head, flogged him, and assigned him to the armorers' ward." },
  { zh: "居三年，演又因諫爭，大被歐撻，閉口不食。", literal: "After three years Yan again remonstrated in dispute, was greatly beaten, closed his mouth, and would not eat.", idiomatic: "After three years Yan again remonstrated in dispute, was greatly beaten, closed his mouth, and would not eat." },
  { zh: "太后日夜涕泣，帝不知所為，曰：「倘小兒死，奈我老母何！", literal: "The empress dowager wept day and night; the emperor did not know what to do and said, \"If the little boy dies, what of my old mother!", idiomatic: "The empress dowager wept day and night; the emperor did not know what to do and said, \"If the little boy dies, what of my old mother!" },
  { zh: "」於是數往問演疾，謂曰：「努力強食，當以王晞還汝。", literal: "\" He then several times went to inquire after Yan's illness and said, \"Strive to eat forcefully—I will return Wang Xi to you.", idiomatic: "\" He then several times went to inquire after Yan's illness and said, \"Strive to eat forcefully—I will return Wang Xi to you." },
  { zh: "」乃釋晞，令詣演。", literal: "\" He then released Xi and ordered him to go to Yan.", idiomatic: "\" He then released Xi and ordered him to go to Yan." },
  { zh: "演抱晞曰：「吾氣息惙然，恐不復相見！", literal: "Yan embraced Xi and said, \"My breath is faint—I fear we shall not meet again!", idiomatic: "Yan embraced Xi and said, \"My breath is faint—I fear we shall not meet again!" },
  { zh: "」晞流涕曰：「天道神明，豈令殿下遂斃此捨！", literal: "\" Xi wept and said, \"Heaven's way and the spirits—how could they let Your Highness die in this hut!", idiomatic: "\" Xi wept and said, \"Heaven's way and the spirits—how could they let Your Highness die in this hut!" },
  { zh: "至尊親為人兄，尊為人主，安可與計！", literal: "The sovereign is elder brother in person and exalted as lord—how can one reckon with him!", idiomatic: "The sovereign is elder brother in person and exalted as lord—how can one reckon with him!" },
  { zh: "殿下不食，太后亦不食。", literal: "If Your Highness does not eat, the empress dowager also will not eat.", idiomatic: "If Your Highness does not eat, the empress dowager also will not eat." },
  { zh: "殿下縱不自惜，獨不念太后乎！", literal: "Though Your Highness may not spare yourself, will you not think of the empress dowager!", idiomatic: "Though Your Highness may not spare yourself, will you not think of the empress dowager!" },
  { zh: "」言未卒，演強坐而飯。", literal: "\" Before the words ended, Yan forced himself to sit up and eat.", idiomatic: "\" Before the words ended, Yan forced himself to sit up and eat." },
  { zh: "晞由是得免徙，還為王友。", literal: "Xi thereby escaped exile and returned to serve as the prince's companion.", idiomatic: "Xi thereby escaped exile and returned to serve as the prince's companion." },
  { zh: "及演錄尚書事，除官者皆詣演謝，去必辭。", literal: "When Yan became Recorder of the Secretariat, those receiving appointments all went to Yan to give thanks and on leaving always took leave.", idiomatic: "When Yan became recorder of the secretariat, those receiving appointments all went to Yan to give thanks and on leaving always took leave." },
  { zh: "晞言於演曰：「受爵天朝，拜恩私第，自古以為不可，宜一切約絕。", literal: "Xi said to Yan, \"To receive rank from the heavenly court and bow in thanks at a private residence has from antiquity been held impossible—one should cut it off entirely.", idiomatic: "Xi said to Yan, \"To receive rank from the heavenly court and bow in thanks at a private residence has from antiquity been held impossible—one should cut it off entirely." },
  { zh: "」演從之。", literal: "\" Yan followed this.", idiomatic: "\" Yan followed this." },
  { zh: "久之，演從容謂晞曰：「主上起居不恆，卿宜耳目所具，吾豈可以前逢一怒，遂爾結舌。", literal: "After long time Yan said calmly to Xi, \"Our lord's conduct is not constant—you should have what eyes and ears provide; how can I, because I once met rage, thus seal my lips.", idiomatic: "After long time Yan said calmly to Xi, \"Our lord's conduct is not constant—you should have what eyes and ears provide; how can I, because I once met rage, thus seal my lips." },
  { zh: "卿宜為撰諫草，吾當伺便極諫。", literal: "You should draft remonstrance for me; I will watch for an opening and remonstrate to the limit.", idiomatic: "You should draft remonstrance for me; I will watch for an opening and remonstrate to the limit." },
  { zh: "」晞遂條十餘事以呈，因謂演曰：「今朝廷所恃者惟殿下，乃欲學匹夫耿介，輕一朝之命！", literal: "\" Xi then set out more than ten matters to present, and said to Yan, \"Now whom the court relies on is only Your Highness—yet you wish to study the obstinacy of a common man and lightly throw away a morning's life!", idiomatic: "\" Xi then set out more than ten matters to present, and said to Yan, \"Now whom the court relies on is only Your Highness—yet you wish to study the obstinacy of a common man and lightly throw away a morning's life!" },
  { zh: "狂藥令人不自覺，刀箭豈復識親疏。", literal: "Mad medicine makes men unaware of themselves—do blades and arrows still know near from far!", idiomatic: "Mad medicine makes men unaware of themselves—do blades and arrows still know near from far!" },
  { zh: "一旦禍出理外，將奈殿下家業何！", literal: "Once disaster comes outside reason, what of Your Highness's house and estate!", idiomatic: "Once disaster comes outside reason, what of Your Highness's house and estate!" },
  { zh: "奈皇太后何！", literal: "What of the empress dowager!", idiomatic: "What of the empress dowager!" },
  { zh: "」演欷歔不自勝，曰：「乃至是乎！", literal: "\" Yan sobbed and could not overcome himself, saying, \"Has it come to this!", idiomatic: "\" Yan sobbed and could not overcome himself, saying, \"Has it come to this!" },
  { zh: "」明日，見晞曰：「吾長夜久思，今遂息意。", literal: "\" Next day he saw Xi and said, \"I thought long through the night; now I rest my intent.", idiomatic: "\" Next day he saw Xi and said, \"I thought long through the night; now I rest my intent." },
  { zh: "」即命火，對晞焚之。", literal: "\" He then ordered fire and burned it before Xi.", idiomatic: "\" He then ordered fire and burned it before Xi." },
  { zh: "後復承間苦諫，帝使力士反接，拔白刃注頸，罵曰：「小子何知，是誰教汝？", literal: "Later he again seized an opening for bitter remonstrance; the emperor had strongmen bind his arms behind him, drew a white blade and set it at his neck, and cursed, \"What does a boy know—who taught you!", idiomatic: "Later he again seized an opening for bitter remonstrance; the emperor had strongmen bind his arms behind him, drew a white blade and set it at his neck, and cursed, \"What does a boy know—who taught you!" },
  { zh: "」演曰：「天下噤口，非臣誰敢有言！", literal: "\" Yan said, \"The world is mute—besides your servant who dares speak!", idiomatic: "\" Yan said, \"The world is mute—besides your servant who dares speak!" },
  { zh: "」帝趣杖，亂捶之數十；", literal: "\" The emperor hurried for the staff and beat him chaotically several tens of times;", idiomatic: "\" The emperor hurried for the staff and beat him chaotically several tens of times;" },
  { zh: "會醉臥，得解。", literal: "he happened to fall drunk asleep, and Yan was released.", idiomatic: "he happened to fall drunk asleep, and Yan was released." },
  { zh: "帝褻黷之遊，遍於宗戚，所往留連；", literal: "The emperor's licentious diversions spread through the clan; wherever he went he lingered;", idiomatic: "The emperor's licentious diversions spread through the clan; wherever he went he lingered;" },
  { zh: "唯至常山第，多無適而去。", literal: "only when he reached the Changshan residence did he mostly leave without pleasure.", idiomatic: "only when he reached the Changshan residence did he mostly leave without pleasure." },
  { zh: "尚書左僕射崔暹屢諫，演謂暹曰：「今太后不敢致言，吾兄弟杜口，僕射獨能犯顏，內外深相愧感。", literal: "Left Vice Director of the Secretariat Cui Xian remonstrated repeatedly; Yan said to Xian, \"Now the empress dowager dares not speak; we brothers seal our mouths—only the vice director can offend the countenance; inside and outside we deeply feel shame and gratitude.", idiomatic: "Left vice director of the secretariat Cui Xian remonstrated repeatedly; Yan said to Xian, \"Now the empress dowager dares not speak; we brothers seal our mouths—only the vice director can offend the countenance; inside and outside we deeply feel shame and gratitude." },
  { zh: "太子殷，自幼溫裕開朗，禮士好學，關覽時政，甚有美名。", literal: "Crown Prince Yin from youth was warm, generous, and open, honored scholars and loved learning, surveyed current affairs, and had a fine reputation.", idiomatic: "Crown Prince Yin from youth was warm, generous, and open, honored scholars and loved learning, surveyed current affairs, and had a fine reputation." },
  { zh: "帝嘗嫌太子「得漢家性質，不似我」，欲廢之。", literal: "The emperor once disliked that the crown prince \"has Han family nature, not like me\" and wished to set him aside.", idiomatic: "The emperor once disliked that the crown prince \"has Han family nature, not like me\" and wished to set him aside." },
  { zh: "帝登金鳳台，召太子，使手刃囚，太子惻然有難色，再三，不斷其首。", literal: "The emperor ascended Golden Phoenix Terrace, summoned the crown prince, and made him personally blade a prisoner; the crown prince looked compassionate and had a troubled face; again and again he would not sever the head.", idiomatic: "The emperor ascended Golden Phoenix Terrace, summoned the crown prince, and made him personally blade a prisoner; the crown prince looked compassionate and had a troubled face; again and again he would not sever the head." },
  { zh: "帝大怒，親以馬鞭撞之，太子由是氣悸語吃，精神昏擾。", literal: "The emperor was greatly angered and personally struck him with a horsewhip; the crown prince thereby had palpitations, stammered in speech, and his spirit was dazed and troubled.", idiomatic: "The emperor was greatly angered and personally struck him with a horsewhip; the crown prince thereby had palpitations, stammered in speech, and his spirit was dazed and troubled." },
  { zh: "帝因酣宴，屢云：「太子性懦，社稷事重，終當傳位常山。", literal: "The emperor at a drunken feast repeatedly said, \"The crown prince's nature is timid; the altars of state are weighty—the throne will in the end pass to Changshan.", idiomatic: "The emperor at a drunken feast repeatedly said, \"The crown prince's nature is timid; the altars of state are weighty—the throne will in the end pass to Changshan." },
  { zh: "」太子少傅魏收謂楊愔曰：「太子，國之根本，不可動搖。", literal: "\" The crown prince's junior tutor Wei Shou said to Yang Yin, \"The crown prince is the state's root—it cannot be shaken.", idiomatic: "\" The crown prince's junior tutor Wei Shou said to Yang Yin, \"The crown prince is the state's root—it cannot be shaken." },
  { zh: "至尊三爵之後，每言傳位常山，令臣下疑貳。", literal: "After three cups the sovereign each time speaks of passing the throne to Changshan, making ministers doubt and divide.", idiomatic: "After three cups the sovereign each time speaks of passing the throne to Changshan, making ministers doubt and divide." },
  { zh: "若其實也，當決行之。", literal: "If it is real, it should be carried out decisively.", idiomatic: "If it is real, it should be carried out decisively." },
  { zh: "此言非所以為戲，恐徒使國家不安。", literal: "This talk is not for sport—I fear it will only make the state unsteady.", idiomatic: "This talk is not for sport—I fear it will only make the state unsteady." },
  { zh: "」愔以收言白帝，帝乃止。", literal: "\" Yin reported Shou's words to the emperor, and he then stopped.", idiomatic: "\" Yin reported Shou's words to the emperor, and he then stopped." },
  { zh: "帝既殘忍，有司訊囚，莫不嚴酷，或燒犁耳，使立其上，或燒車釭，使以臂貫之，既不勝苦，皆至誣伏。", literal: "The emperor being cruel, offices interrogating prisoners were all severe; some burned plow ears and made men stand on them, some burned chariot hubs and made them thread their arms through; unable to bear the pain, all came to false confession.", idiomatic: "The emperor being cruel, offices interrogating prisoners were all severe; some burned plow ears and made men stand on them, some burned chariot hubs and made them thread their arms through; unable to bear the pain, all came to false confession." },
  { zh: "唯三公郎中武強蘇瓊，歷職中外，所至皆以寬平為治。", literal: "Only Secretariat gentleman Su Qiong of Wuqiang, serving inside and outside, everywhere governed with lenience and fairness.", idiomatic: "Only secretariat gentleman Su Qiong of Wuqiang, serving inside and outside, everywhere governed with lenience and fairness." },
  { zh: "時趙州及清河屢有人告謀反者，前後皆付瓊推檢，事多申雪。", literal: "At that time in Zhao commandery and Qinghe men repeatedly reported rebellion; case after case was entrusted to Qiong for investigation, and many were cleared of wrong.", idiomatic: "At that time in Zhao commandery and Qinghe men repeatedly reported rebellion; case after case was entrusted to Qiong for investigation, and many were cleared of wrong." },
  { zh: "尚書崔昂謂瓊曰：「若欲立功名，當更思餘理；", literal: "Secretariat Director Cui Ang said to Qiong, \"If you wish to establish merit and fame, you should think of other methods;", idiomatic: "Secretariat director Cui Ang said to Qiong, \"If you wish to establish merit and fame, you should think of other methods;" },
  { zh: "數雪反逆，身命何輕！", literal: "again and again clearing rebels—how lightly you hold your life!", idiomatic: "again and again clearing rebels—how lightly you hold your life!" },
  { zh: "」瓊正色曰：「所雪者冤枉耳，不縱反逆也。", literal: "\" Qiong said sternly, \"What I clear is wrongful accusation—I do not indulge rebels.", idiomatic: "\" Qiong said sternly, \"What I clear is wrongful accusation—I do not indulge rebels." },
  { zh: "」昂大慚。", literal: "\" Ang was greatly ashamed.", idiomatic: "\" Ang was greatly ashamed." },
  { zh: "帝怒臨漳令稽曄、舍人李文師，以賜臣下為奴。", literal: "The emperor was angry at Linzhang magistrate Ji Ye and Attendant Li Wenshi and gave them as slaves to ministers.", idiomatic: "The emperor was angry at Linzhang magistrate Ji Ye and attendant Li Wenshi and gave them as slaves to ministers." },
  { zh: "中書侍郎彭城鄭頤私誘祠部尚書王昕曰：「自古無朝士為奴者。", literal: "Secretariat Gentleman Zheng Yi of Pengcheng privately enticed Director of Sacrifices Wang Xin, saying, \"From antiquity there has been no court gentleman made a slave.", idiomatic: "Secretariat gentleman Zheng Yi of Pengcheng privately enticed director of sacrifices Wang Xin, saying, \"From antiquity there has been no court gentleman made a slave." },
  { zh: "」昕曰：「箕子為之奴。", literal: "\" Xin said, \"Jizi became a slave.", idiomatic: "\" Xin said, \"Jizi became a slave." },
  { zh: "」頤以白帝曰：「王元景比陛下於紂。", literal: "\" Yi reported to the emperor, \"Wang Yuanjing compares Your Majesty to Zhou of Shang.", idiomatic: "\" Yi reported to the emperor, \"Wang Yuanjing compares Your Majesty to Zhou of Shang." },
  { zh: "」帝銜之。", literal: "\" The emperor bore a grudge.", idiomatic: "\" The emperor bore a grudge." },
  { zh: "頃之，帝與朝臣酣飲，昕稱疾不至，帝遣騎執之，見方搖膝吟詠，遂斬於殿前，投屍漳水。", literal: "Before long the emperor drank deeply with court ministers; Xin claimed illness and did not come; the emperor sent horsemen to seize him, saw him swaying his knees and chanting, and beheaded him before the hall, casting the corpse into Zhang River.", idiomatic: "Before long the emperor drank deeply with court ministers; Xin claimed illness and did not come; the emperor sent horsemen to seize him, saw him swaying his knees and chanting, and beheaded him before the hall, casting the corpse into Zhang River." },
  { zh: "齊主北築長城，南助蕭莊，士馬死者以數十萬。", literal: "The Qi ruler built the Long Wall in the north and aided Xiao Zhuang in the south; soldiers and horses dead numbered in the hundreds of thousands.", idiomatic: "The Qi ruler built the Long Wall in the north and aided Xiao Zhuang in the south; soldiers and horses dead numbered in the hundreds of thousands." },
  { zh: "重以修築台殿，賜與無節，府藏之積，不足以供，乃減百官之祿，撤軍人常廩，並省州郡縣鎮戍之職，以節費用焉。", literal: "Added to this were terrace halls and palaces, gifts without measure; treasury stores were not enough to supply them; salaries of the hundred officials were reduced, soldiers' regular rations withdrawn, and posts in provinces, commanderies, counties, and garrison forts were cut together to economize.", idiomatic: "Added to this were terrace halls and palaces, gifts without measure; treasury stores were not enough to supply them; salaries of the hundred officials were reduced, soldiers' regular rations withdrawn, and posts in provinces, commanderies, counties, and garrison forts were cut together to economize." },
  { zh: "十二月，庚寅，齊以可朱渾道元為太師，尉粲為太尉，冀州刺史段韶為司空，常山王演為大司馬，長廣王湛為司徒。", literal: "Twelfth month, on gengyin, Qi made Kezhuhun Daoyuan Grand Preceptor, Yu Can Grand Commander, Jizhou Inspector Duan Shao Minister of Works, Prince Yan of Changshan Grand Marshal, and Prince Zhan of Changgung Minister of Education.", idiomatic: "Twelfth month, on gengyin, Qi made Kezhuhun Daoyuan grand preceptor, Yu Can grand commander, Jizhou inspector Duan Shao minister of works, Prince Yan of Changshan grand marshal, and Prince Zhan of Changgung minister of education." },
  { zh: "壬午，周大赦。", literal: "On renwu, Zhou proclaimed a general amnesty.", idiomatic: "On renwu, Northern Zhou proclaimed a general amnesty." },
  { zh: "齊主如北城，因視永安簡平王浚、上黨剛肅王渙於地牢。", literal: "The Qi ruler went to the north city and thereby viewed Prince Jun of Yong'an, posthumous Jianping, and Prince Huan of Shangdang, posthumous Gangsu, in the dungeon.", idiomatic: "The Qi ruler went to the north city and thereby viewed Prince Jun of Yong'an, posthumous Jianping, and Prince Huan of Shangdang, posthumous Gangsu, in the dungeon." },
  { zh: "帝臨穴謳歌，令浚等和之，浚等惶怖且悲，不覺聲顫；", literal: "The emperor at the pit mouth sang songs and ordered Jun and the rest to harmonize; Jun and the rest were fearful and grieved, unconsciously their voices trembled;", idiomatic: "The emperor at the pit mouth sang songs and ordered Jun and the rest to harmonize; Jun and the rest were fearful and grieved, unconsciously their voices trembled;" },
  { zh: "帝愴然，為之下泣，將赦之。", literal: "the emperor was moved, wept for them, and was about to pardon them.", idiomatic: "the emperor was moved, wept for them, and was about to pardon them." },
  { zh: "長廣王湛素與浚不睦，進曰：「猛虎安可出穴！", literal: "Prince Zhan of Changgung had long been at odds with Jun and advanced, saying, \"How can a fierce tiger be let out of its den!", idiomatic: "Prince Zhan of Changgung had long been at odds with Jun and advanced, saying, \"How can a fierce tiger be let out of its den!" },
  { zh: "」帝默然。", literal: "\" The emperor was silent.", idiomatic: "\" The emperor was silent." },
  { zh: "浚等聞之，呼湛小字曰：「步落稽，皇天見汝！", literal: "Jun and the rest hearing this called Zhan by his childhood name, saying, \"Buluoqi—Heaven sees you!", idiomatic: "Jun and the rest hearing this called Zhan by his childhood name, saying, \"Buluoqi—Heaven sees you!" },
  { zh: "」帝亦以浚與渙皆有雄略，恐為後害，乃自刺渙，又使壯士劉桃枝就籠亂刺。", literal: "\" The emperor also, because Jun and Huan both had bold strategies, feared them as future harm; he himself stabbed Huan and also sent the strongman Liu Taozhi to the cage for chaotic stabbing.", idiomatic: "\" The emperor also, because Jun and Huan both had bold strategies, feared them as future harm; he himself stabbed Huan and also sent the strongman Liu Taozhi to the cage for chaotic stabbing." },
  { zh: "槊每下，浚、渙輒以手拉折之，號哭呼天。", literal: "Each time the spear came down, Jun and Huan would pull and break it with their hands, wailing and calling to Heaven.", idiomatic: "Each time the spear came down, Jun and Huan would pull and break it with their hands, wailing and calling to Heaven." },
  { zh: "於是薪火亂投，燒殺之，填以土石。", literal: "Thereupon firewood was thrown in confusion, burning them to death; earth and stone filled them in.", idiomatic: "Thereupon firewood was thrown in confusion, burning them to death; earth and stone filled them in." },
  { zh: "後出之，皮發皆盡，屍色如炭，遠近為之痛憤。", literal: "Later when they were dug out, skin and hair were all gone; the corpses were charcoal-colored; near and far were pained and outraged.", idiomatic: "Later when they were dug out, skin and hair were all gone; the corpses were charcoal-colored; near and far were pained and outraged." },
  { zh: "帝以儀同三司劉郁捷殺浚，以浚妃陸氏賜之；", literal: "The emperor because Palace Attendant of the Third Rank Liu Yu had killed Jun swiftly gave him Jun's consort Lady Lu;", idiomatic: "The emperor because palace attendant of the third rank Liu Yu had killed Jun swiftly gave him Jun's consort Lady Lu;" },
  { zh: "馮文洛殺渙，以渙妃李氏賜之，二人皆帝家舊奴也。", literal: "Feng Wenluo had killed Huan and was given Huan's consort Lady Li—both men were old slaves of the imperial house.", idiomatic: "Feng Wenluo had killed Huan and was given Huan's consort Lady Li—both men were old slaves of the imperial house." },
  { zh: "陸氏尋以無寵於浚，得免。", literal: "Lady Lu soon, because she had no favor with Jun, was spared.", idiomatic: "Lady Lu soon, because she had no favor with Jun, was spared." },
  { zh: "高涼太守馮寶卒，海隅擾亂。", literal: "Gaoliang Administrator Feng Bao died; the seacoast was disturbed.", idiomatic: "Gaoliang administrator Feng Bao died; the seacoast was disturbed." },
  { zh: "妻洗氏懷集部落，數州晏然。", literal: "His wife Lady Xian gathered the tribes; several provinces were tranquil.", idiomatic: "His wife Lady Xian gathered the tribes; several provinces were tranquil." },
  { zh: "其子僕，生九年，是歲，遣僕帥諸酋長入朝，詔以僕為陽春太守。", literal: "His son Pu, nine years old that year, was sent leading various chieftains to court; an edict made Pu Administrator of Yangchun.", idiomatic: "His son Pu, nine years old that year, was sent leading various chieftains to court; an edict made Pu administrator of Yangchun." },
  { zh: "後梁主遣其大將軍王操將兵略取王琳之長沙、武陵、南平等郡。", literal: "The Later Liang ruler sent his Grand General Wang Cao to lead troops and seize Wang Lin's commanderies of Changsha, Wuling, Nanping, and others.", idiomatic: "The Later Liang ruler sent his grand general Wang Cao to lead troops and seize Wang Lin's commanderies of Changsha, Wuling, Nanping, and others." },
  { zh: "春，正月，己酉，周太師護上表歸政，周王始親萬機；", literal: "Spring, first month, on jiyou, Zhou Grand Preceptor Hu memorialized returning government; the Zhou king began personally to handle the myriad affairs;", idiomatic: "Spring, first month, on jiyou, Northern Zhou grand preceptor Hu memorialized returning government; the Zhou king began personally to handle the myriad affairs;" },
  { zh: "軍旅之事，護猶總之。", literal: "military affairs Hu still oversaw in total.", idiomatic: "military affairs Hu still oversaw in total." },
  { zh: "初改都督軍州事為總管。", literal: "For the first time the title of commander over military affairs of provinces and commanderies was changed to overall commander.", idiomatic: "For the first time the title of commander over military affairs of provinces and commanderies was changed to overall commander." },
  { zh: "王琳召桂州刺史淳於量。", literal: "Wang Lin summoned Chunyu Liang, inspector of Guizhou.", idiomatic: "Wang Lin summoned Chunyu Liang, inspector of Guizhou." },
  { zh: "量雖與琳合，而潛通於陳；", literal: "Though Liang had joined with Lin, he secretly communicated with Chen;", idiomatic: "Though Liang had allied with Lin, he was secretly in contact with Chen;" },
  { zh: "二月，辛酉，以量為開府儀同三司。", literal: "In the second month, on xinyou, Liang was made Grand Master of Splendid Happiness with privileges equal to the Three Excellencies.", idiomatic: "In the second month, on xinyou, Liang was made grand master of splendid happiness with privileges equal to the three excellencies." },
  { zh: "壬午，侯瑱引兵焚齊舟艦於合肥。", literal: "On renwu, Hou Tian led troops and burned Qi ships at Hefei.", idiomatic: "On renwu, Hou Tian led troops and burned Qi ships at Hefei." },
  { zh: "丙戌，齊主於甘露寺禪居深觀，唯軍國大事乃以聞。", literal: "On bingxu, the Qi ruler took up deep meditation at Ganlu Temple; only army and state affairs were reported to him.", idiomatic: "On bingxu, the Qi ruler withdrew into deep meditation at Ganlu Temple; only military and state affairs were brought to his attention." },
  { zh: "尚書右僕射崔暹卒，齊主幸其第哭之，謂其妻李氏曰：「頗思暹乎？", literal: "Right Vice Director Cui Xuan died. The Qi ruler visited his house to mourn and said to his wife Lady Li, \"Do you miss Xuan much?\"", idiomatic: "Right vice director Cui Xuan died. The Qi ruler visited his home to mourn and asked his wife Lady Li, \"Do you miss Xuan?\"" },
  { zh: "」對曰：「思之。", literal: "\"She answered, \"I do.\"", idiomatic: "\"She answered, \"I do.\"" },
  { zh: "」帝曰：「然則自往省之。", literal: "\"The emperor said, \"Then go visit him yourself.\"", idiomatic: "\"The emperor said, \"Then go visit him yourself.\"" },
  { zh: "」因手斬其妻，擲首牆外。", literal: "He then cut off her head with his own hand and threw it outside the wall.", idiomatic: "With his own hand he cut off her head and threw it beyond the wall." },
  { zh: "齊斛律光將騎一萬，擊周開府儀同三司曹回公，斬之，柏谷城主薛禹生棄城走，遂取文侯鎮，立戍置柵而還。", literal: "Qi's Hu Lv Guang led ten thousand horsemen, struck Zhou's Grand Master of Splendid Happiness Cao Huigong, and beheaded him. Xue Yusheng, lord of Baigu, abandoned the city and fled. They then took Wenhou garrison, set guards and palisades, and returned.", idiomatic: "Northern Qi's Hu Lv Guang led ten thousand horsemen against Zhou's grand master of splendid happiness Cao Huigong, beheaded him, and drove Xue Yusheng, lord of Baigu, from his city. He took Wenhou garrison, left guards and palisades, and returned." },
  { zh: "三月，戊戌，齊以侍中高德政為尚書右僕射。", literal: "In the third month, on wuxu, Qi made Palace Attendant Gao Dezheng Right Vice Director.", idiomatic: "In the third month, on wuxu, Qi made palace attendant Gao Dezheng right vice director." },
  { zh: "吐谷渾寇周邊；", literal: "Tuyuhun raided Zhou's borders;", idiomatic: "Tuyuhun raided Zhou's borders;" },
  { zh: "庚戌，周遣大司馬賀蘭祥擊之。", literal: "on gengxu, Zhou sent Grand Marshal Helan Xiang to strike them.", idiomatic: "on gengxu, Northern Zhou sent grand marshal Helan Xiang against them." },
  { zh: "丙辰，齊主至鄴。", literal: "on bingchen, the Qi ruler reached Ye.", idiomatic: "on bingchen, the Qi ruler reached Ye." },
  { zh: "梁永嘉王莊至郢州，遣使入貢於齊。", literal: "Liang's Prince Zhuang of Yongjia arrived at Yingzhou and sent envoys to offer tribute to Qi.", idiomatic: "Liang's Prince Zhuang of Yongjia arrived at Yingzhou and sent envoys to offer tribute to Qi." },
  { zh: "王琳遣其將雷文策襲後梁監利太守蔡大有，殺之。", literal: "Wang Lin sent his general Lei Wence to raid Later Liang's acting inspector of Jianli, Cai Dayou, and killed him.", idiomatic: "Wang Lin sent his general Lei Wence to raid Later Liang's acting inspector of Jianli, Cai Dayou, and killed him." },
  { zh: "齊主之為魏相也，膠州刺史定陽文肅侯杜弼為長史，帝將受禪，弼諫止之。", literal: "When the Qi ruler had been Wei's chancellor, Du Bi of Dingyang, Marquis Wen and Su of Jiaozhou, was his chief clerk. When the emperor was about to receive the abdication, Bi remonstrated and stopped it.", idiomatic: "When the Qi ruler had been Wei's chancellor, Du Bi of Dingyang, marquis Wen and Su of Jiaozhou, had been his chief clerk. When the emperor was about to accept the abdication, Bi remonstrated and stopped it." },
  { zh: "帝問：「治國當用何人？", literal: "The emperor asked, \"Whom should one use to govern the realm?\"", idiomatic: "The emperor asked, \"Whom should one use to govern the realm?\"" },
  { zh: "」對曰：「鮮卑車馬客，會須用中國人。", literal: "\"He answered, \"For Xianbei charioteers and horse-guests, one must still use Chinese men.\"", idiomatic: "\"He answered, \"For Xianbei drivers and camp followers, one must still employ Chinese men.\"" },
  { zh: "」帝以為譏己，銜之。", literal: "The emperor took this as mockery of himself and harbored resentment.", idiomatic: "The emperor took this as a barb aimed at himself and nursed resentment." },
  { zh: "高德政用事，弼不為之下，嘗於眾前面折德政；", literal: "Gao Dezheng held power; Bi would not submit to him and once rebuked Dezheng to his face before the assembly;", idiomatic: "Gao Dezheng held power; Bi would not bow to him and once shamed Dezheng before the whole court;" },
  { zh: "德政數言其短於帝，弼恃舊，不自疑。", literal: "Dezheng repeatedly reported his faults to the emperor. Bi, relying on old ties, did not suspect harm.", idiomatic: "Dezheng repeatedly denounced him to the emperor. Bi, trusting old acquaintance, never suspected danger." },
  { zh: "夏，帝因飲酒，積其愆失，遣使就州斬之；", literal: "In summer, the emperor, while drinking, tallied his accumulated faults and sent an envoy to the province to behead him;", idiomatic: "In summer, while drinking, the emperor tallied his accumulated faults and sent an envoy to behead him in his province;" },
  { zh: "既而悔之，驛追不及。", literal: "then he regretted it, but post-horses could not overtake the execution.", idiomatic: "then regretted it—but relay horses could not catch up." },
  { zh: "閏四月，戊子，周命有司更定新歷。", literal: "In the intercalary fourth month, on wuzi, Zhou ordered the offices to revise the new calendar anew.", idiomatic: "In the intercalary fourth month, on wuzi, Northern Zhou ordered the offices to revise the calendar anew." },
  { zh: "丁酉，遣鎮北將軍徐度將兵志南皖口。", literal: "On dingyou, General Who Pacifies the North Xu Du was sent to lead troops to encamp at Nanwankou.", idiomatic: "On dingyou, general who pacifies the north Xu Du was sent to lead troops and encamp at Nanwankou." },
  { zh: "齊高德政與楊愔同為相，愔常忌之。", literal: "Qi's Gao Dezheng and Yang Yin were both chancellors; Yin often resented him.", idiomatic: "Qi's Gao Dezheng and Yang Yin were both chancellors; Yin often resented him." },
  { zh: "齊主酣飲，德政數強諫，齊主不悅，謂左右曰：「高德政恆以精神凌逼人。", literal: "The Qi ruler drank deep. Dezheng repeatedly remonstrated forcefully; the ruler was displeased and told those about him, \"Gao Dezheng always overwhelms people with his spirit.\"", idiomatic: "The Qi ruler drank deep. Dezheng remonstrated again and again; the ruler was displeased and told his attendants, \"Gao Dezheng always crushes people with his spirit.\"" },
  { zh: "」德政懼，稱疾，欲自退。", literal: "Dezheng was afraid, claimed illness, and wished to withdraw.", idiomatic: "Dezheng grew afraid, pleaded illness, and wished to withdraw." },
  { zh: "帝謂楊愔曰：「我大憂德政病。", literal: "The emperor said to Yang Yin, \"I am greatly worried that Dezheng is ill.\"", idiomatic: "The emperor said to Yang Yin, \"I am deeply worried that Dezheng is ill.\"" },
  { zh: "」對曰：「陛下若用為冀州刺史，病當自差。", literal: "\"Yin answered, \"If Your Majesty appoints him Inspector of Jizhou, the illness will cure itself.\"", idiomatic: "\"Yin answered, \"If Your Majesty makes him inspector of Jizhou, the illness will cure itself.\"" },
  { zh: "」帝從之。", literal: "The emperor followed this.", idiomatic: "The emperor followed this." },
  { zh: "德政見除書，即起。", literal: "When Dezheng saw the appointment order, he rose at once.", idiomatic: "When Dezheng saw the appointment order, he rose at once." },
  { zh: "帝大怒，召德政謂曰：「聞爾病，我為爾針。", literal: "The emperor was greatly enraged, summoned Dezheng, and said, \"I heard you were ill—I will needle you for it.\"", idiomatic: "The emperor was furious, summoned Dezheng, and said, \"I heard you were ill—I will give you acupuncture.\"" },
  { zh: "」親以小刀刺之，血流沾地。", literal: "He personally pricked him with a small knife until blood soaked the ground.", idiomatic: "He personally pricked him with a small knife until blood pooled on the floor." },
  { zh: "又使曳下斬去其足，劉桃枝執刀不敢下，帝責桃枝曰：「爾頭即墜地！", literal: "He also had him dragged down and his feet cut off. Liu Taozhi held the blade but dared not strike. The emperor rebuked Taozhi: \"Your head will fall to the ground next!\"", idiomatic: "He had him dragged down to cut off his feet. Liu Taozhi held the blade but dared not strike. The emperor shouted, \"Your head is next!\"" },
  { zh: "」桃枝乃斬其足之三指。", literal: "Taozhi then cut off three toes of each foot.", idiomatic: "Taozhi then cut off three toes from each foot." },
  { zh: "帝怒不解，囚德政於門下，其夜，以氈輿送還家。", literal: "The emperor's rage did not ease. He imprisoned Dezheng at the Gate Department; that night he had him sent home in a felt litter.", idiomatic: "The emperor's rage did not ease. He imprisoned Dezheng at the Gate Department; that night he sent him home in a felt litter." },
  { zh: "明旦，德政妻出珍寶滿四床，欲以寄人，帝奄至其宅，見之，怒曰：「我內府猶無是物！", literal: "At dawn the next day, Dezheng's wife brought out treasures filling four beds, intending to lodge them with others. The emperor came suddenly upon the house, saw them, and raged: \"Even my inner treasury has nothing like this!\"", idiomatic: "At dawn Dezheng's wife brought out treasures heaped on four beds, intending to lodge them elsewhere. The emperor burst in, saw them, and raged: \"Even my inner treasury has nothing like this!\"" },
  { zh: "」詰其所從得，皆諸元賂之，遂曳出，斬之。", literal: "He interrogated where they came from—all were bribes from various Yuans—and had him dragged out and beheaded.", idiomatic: "He demanded their source—all were bribes from the Yuans—and had Dezheng dragged out and beheaded." },
  { zh: "妻出拜，又斬之，並其子伯堅。", literal: "When the wife came out to bow, he beheaded her too, together with their son Bojian.", idiomatic: "When the wife came out to bow, he beheaded her as well, together with their son Bojian." },
  { zh: "以司州牧彭城王浟為司空，侍中高陽王湜為尚書右僕射；", literal: "Prince You of Pengcheng was made Minister of Works, and Prince Shi of Gaoyang Right Vice Director;", idiomatic: "Prince You of Pengcheng was made minister of works, and Prince Shi of Gaoyang right vice director;" },
  { zh: "乙巳，以浟兼太尉。", literal: "on yisi, You was also made Grand Commandant.", idiomatic: "on yisi, You was also made grand commandant." },
  { zh: "齊主封子紹廉為長安王。", literal: "The Qi ruler enfeoffed his son Shaoqian as Prince of Chang'an.", idiomatic: "The Qi ruler enfeoffed his son Shaoqian as prince of Chang'an." },
  { zh: "辛亥，周以侯莫陳崇為大司徒，達奚武為大宗伯，武陽公豆盧寧為大司寇，柱國輔城公邕為大司空。", literal: "On xinhai, Zhou made Hou Mo Chenchong Grand Minister of Education, Daxi Wu Grand Director of the Masses, Duke Ning of Wuyang Dou Lu'ning Grand Judge, and Duke Yong of Fucheng Yu the Grand Minister of Works.", idiomatic: "On xinhai, Northern Zhou made Hou Mo Chenchong grand minister of education, Daxi Wu grand director of the masses, Duke Ning of Wuyang Dou Lu'ning grand judge, and Duke Yong of Fucheng Yu grand minister of works." },
  { zh: "乙卯，周詔：「有司無得糾赦前事；", literal: "On yimao, Zhou decreed: \"Offices must not investigate matters before amnesty;", idiomatic: "On yimao, Northern Zhou decreed: \"Offices must not investigate matters covered by amnesty;" },
  { zh: "唯庫廄倉廩與海內所共，若有侵盜，雖經赦宥免其罪，征備如法。", literal: "only treasuries, stables, and granaries are held in common with all under heaven. If there is embezzlement, though amnesty may spare the crime, restitution shall be levied according to law.\"", idiomatic: "only treasuries, stables, and granaries are held in common with all under heaven. If there is theft, though amnesty may spare punishment, restitution shall be exacted by law.\"" },
  { zh: "周賀蘭祥與吐谷渾戰，破之，拔其洮陽、洪和二城，以其地為洮州。", literal: "Zhou's Helan Xiang fought Tuyuhun, defeated them, took their cities Taoyang and Honghe, and made the territory Taozhou.", idiomatic: "Northern Zhou's Helan Xiang defeated Tuyuhun, took Taoyang and Honghe, and organized the region as Taozhou." },
  { zh: "五月，丙辰朔，日有食之。", literal: "In the fifth month, on the first day bingchen, there was a solar eclipse.", idiomatic: "In the fifth month, on the first day bingchen, there was a solar eclipse." },
  { zh: "齊太史奏，今年當除舊布新。", literal: "Qi's grand astrologer reported that this year called for removing the old and spreading the new.", idiomatic: "Qi's grand astrologer reported that the year demanded casting out the old and ushering in the new." },
  { zh: "齊主問於特進彭城公元韶曰：「漢光武何故中興？", literal: "The Qi ruler asked Senior Adviser Yuan Shao of Pengcheng, \"Why did Emperor Guangwu of Han achieve restoration?\"", idiomatic: "The Qi ruler asked senior adviser Yuan Shao of Pengcheng, \"Why did Emperor Guangwu of Han restore the dynasty?\"" },
  { zh: "」對曰：「為誅諸劉不盡。", literal: "\"He answered, \"Because he did not execute all the Lius to the last man.\"", idiomatic: "\"He answered, \"Because he did not slaughter every Liu to the last.\"" },
  { zh: "」於是齊主悉殺諸元以厭之。", literal: "Thereupon the Qi ruler killed all the Yuans to appease the omen.", idiomatic: "Thereupon the Qi ruler killed the Yuans wholesale to satisfy the omen." },
  { zh: "癸未，誅始平公元世哲等二十五家，囚韶等十九家。", literal: "On guiwei, he executed twenty-five clans including Yuan Shizhe of Shiping, and imprisoned nineteen clans including Shao.", idiomatic: "On guiwei he executed twenty-five clans including Yuan Shizhe of Shiping and imprisoned nineteen more including Shao." },
  { zh: "韶幽於地牢，絕食，啗衣袖而死。", literal: "Shao was confined in a dungeon, denied food, and died gnawing his sleeves.", idiomatic: "Shao was shut in a dungeon without food and died gnawing his sleeves." },
  { zh: "周文育、周迪、黃法□共討余公揚，豫章內史熊曇朗引兵會之，眾且萬人。", literal: "Zhou Wenyu, Zhou Di, and Huang Fa□ jointly campaigned against Yu Gongyang. Xiong Tanlang, administrator of Yuzhang, led troops to join them—nearly ten thousand men.", idiomatic: "Zhou Wenyu, Zhou Di, and Huang Fa□ jointly campaigned against Yu Gongyang. Yuzhang administrator Xiong Tanlang brought troops to join them—nearly ten thousand strong." },
  { zh: "文育軍於金口，公揚詐降，謀執文育，文育覺之，囚送建康。", literal: "Wenyu encamped at Jinkou. Gongyang feigned surrender and plotted to seize Wenyu; Wenyu detected it and sent him bound to Jiankang.", idiomatic: "Wenyu encamped at Jinkou. Gongyang feigned surrender and plotted to seize him; Wenyu saw through it and sent him bound to Jiankang." },
  { zh: "文育進屯三陂。", literal: "Wenyu advanced and encamped at Sanpi.", idiomatic: "Wenyu advanced and encamped at Sanpi." },
  { zh: "王琳遣其將曹慶帥二千人救余孝勱，慶分遣主帥常眾愛與文育相拒，自帥其眾攻周迪及安南將軍吳明徹，迪等敗，文育退據金口。", literal: "Wang Lin sent his general Cao Qing with two thousand men to rescue Yu Xiaomo. Qing detached commander Chang Zhong'ai to hold Wenyu at bay and himself led his host to attack Zhou Di and General Who Pacifies the South Wu Mingche. Di and the rest were defeated; Wenyu withdrew to hold Jinkou.", idiomatic: "Wang Lin sent Cao Qing with two thousand men to rescue Yu Xiaomo. Qing detached Chang Zhong'ai to pin Wenyu and himself struck Zhou Di and general who pacifies the south Wu Mingche. Di was beaten; Wenyu fell back on Jinkou." },
  { zh: "熊曇朗因其失利，謀殺文育以應眾愛，監軍孫白象聞其謀，勸文育先之，文育不從。", literal: "Xiong Tanlang, seeing his defeat, plotted to kill Wenyu to join Zhong'ai. Supervisor Sun Baixiang heard the plot and urged Wenyu to strike first; Wenyu would not.", idiomatic: "Xiong Tanlang, seeing Wenyu's setback, plotted to kill him and join Zhong'ai. Supervisor Sun Baixiang learned of it and urged a preemptive strike; Wenyu refused." },
  { zh: "時周迪棄船走，不知所在，乙酉，文育得迪書，自繼以示曇朗，曇朗殺之於座而並其眾，因據新淦城。", literal: "At that time Zhou Di had abandoned his ships and fled—his whereabouts unknown. On yiyou, Wenyu received Di's letter and went in person to show Tanlang; Tanlang killed him at the feast and absorbed his troops, then held Xingan city.", idiomatic: "Zhou Di had abandoned his ships and vanished. On yiyou Wenyu received Di's letter and went in person to show Tanlang; Tanlang killed him at table, took his troops, and seized Xingan." },
  { zh: "曇朗將兵萬人襲周敷，敷擊破之，曇朗單騎奔巴山。", literal: "Tanlang led ten thousand men to raid Zhou Fu; Fu defeated him, and Tanlang fled alone on horseback to Bashan.", idiomatic: "Tanlang led ten thousand men against Zhou Fu; Fu routed him, and Tanlang fled alone to Bashan." },
  { zh: "魯悉達部將梅天養等引齊軍入城。", literal: "Lu Xida's subordinate Mei Tianyang and others led Qi troops into the city.", idiomatic: "Lu Xida's officer Mei Tianyang and others admitted Qi troops into the city." },
  { zh: "悉達帥麾下數千人濟江自歸，拜平南將軍、北江州刺史。", literal: "Xida himself crossed the river with several thousand followers to surrender and was made General Who Pacifies the South and Inspector of North Jiangzhou.", idiomatic: "Xida crossed the Yangtze with several thousand men to surrender and was made general who pacifies the south and inspector of North Jiangzhou." },
  { zh: "六月，戊子，周以霖雨，詔群臣上封事極諫。", literal: "In the sixth month, on wuzi, because of incessant rain Zhou ordered the ministers to submit sealed memorials of utmost remonstrance.", idiomatic: "In the sixth month, on wuzi, after weeks of rain Northern Zhou ordered sealed memorials of frank remonstrance." },
  { zh: "左光祿大夫猗氏樂遜上言四事：其一，以為「比來守令代期既促，責其成效，專務威猛；", literal: "Zuoguanglu Grandee Yue Sun of Yishi submitted four points. First, he held that \"lately the terms of prefects and magistrates have been so short that, pressed for results, they devote themselves solely to severity;", idiomatic: "Left grandee Yue Sun of Yishi offered four points. First: \"Lately prefects and magistrates serve such brief terms that, pressed for results, they rely on nothing but severity;" },
  { zh: "今關東之民淪陷塗炭，若不布政優優，聞諸境外，何以使彼勞民，歸就樂土！", literal: "now the people east of the Pass lie in ruin and ashes. Unless governance is gentle and generous and heard beyond the borders, how can those weary folk be made to return to a land of peace!\"", idiomatic: "the people east of the Pass lie in ashes. Unless rule is gentle and the word reaches beyond our borders, how will those broken folk return to peace?\"" },
  { zh: "」其二，以為「頃者魏都洛陽，一時殷盛，貴勢之家，競為侈靡，終使禍亂交興，天下喪敗；", literal: "\"Second, he held that \"not long ago Wei's capital at Luoyang was for a time immensely prosperous; powerful houses vied in extravagance until calamity and rebellion arose together and the realm was lost;", idiomatic: "\"Second: not long ago Luoyang under Wei flourished beyond measure; great houses raced in luxury until rebellion toppled the realm;" },
  { zh: "比來朝貴器服稍華，百工造作務盡奇巧，臣誠恐物逐好移，有損政俗。", literal: "lately the robes and vessels of court nobles have grown somewhat splendid and the hundred crafts strive for utmost novelty—I truly fear that when things follow taste, custom is harmed.", idiomatic: "lately court dress and vessels grow splendid and craftsmen chase novelty—I fear taste will shift and government with it." },
  { zh: "」其三，以為「選曹補擬，宜舉眾共之；", literal: "\"Third, he held that \"the Selection Office's appointments should be made with the consent of the multitude;", idiomatic: "\"Third: appointments from the Selection Office should rest on common consent;" },
  { zh: "今州郡選置，猶集鄉閭，況天下銓衡，不取物望，既非機事，何足苛密！", literal: "today provincial appointments still gather the village and lane—how much more the scales of the realm, which take no account of public esteem! Since these are not state secrets, why be harshly tight?", idiomatic: "provinces still consult village and lane—how much more the empire's balance, which ignores public regard! These are not state secrets; why such secrecy?" },
  { zh: "其選置之日，宜令眾心明白，然後呈奏。", literal: "On the day of selection, the hearts of the multitude should be clear, and only then should memorials be submitted.", idiomatic: "Let hearts be clear on selection day, then memorialize." },
  { zh: "」其四，以為「高洋據有山東，未易猝制，譬猶棋劫相持，爭行先後，若一行不當，或成彼利。", literal: "\"Fourth, he held that \"Gao Yang's hold on Shandong is not easily overthrown in a rush—it is like a go match in ko, each side racing for precedence; one wrong move may become the other's gain.", idiomatic: "\"Fourth: Gao Yang's hold on Shandong cannot be rushed—it is like ko on the board; one wrong move gifts the advantage." },
  { zh: "誠應捨小營大，先保封域，不宜貪利邊陲，輕為舉動。", literal: "Truly one should forsake small gains to secure large ones, guard the borders first, and not covet profit on the marches or act lightly.", idiomatic: "Forsake small gains for great ones, secure our borders first, and do not grasp at the frontier." },
  { zh: "周處士韋瓊，孝寬之兄也，志尚夷簡。", literal: "Zhou recluse Wei Qiong was elder brother to Wei Xiaokuan, his aim plain and simple.", idiomatic: "Northern Zhou recluse Wei Qiong was Wei Xiaokuan's elder brother, his aims plain and spare." },
  { zh: "魏、周之際，十征不屈。", literal: "Between Wei and Zhou he was summoned ten times and refused each.", idiomatic: "Across Wei and Zhou he was summoned ten times and refused each." },
  { zh: "周太祖甚重之，不奪其志，世宗禮敬尤厚，號曰「逍遙公」。", literal: "Zhou's founding emperor valued him greatly and would not bend his will. Emperor Shizong honored him still more and styled him \"Lord Free Wanderer.\"", idiomatic: "The founding emperor prized him and would not bend his will. Shizong honored him still more and called him Lord Free Wanderer." },
  { zh: "晉公護延之至第，訪以政事；", literal: "Duke Jin Hu invited him to his mansion to consult on government affairs;", idiomatic: "Duke Jin Yuwen Hu invited him to his mansion to discuss government;" },
  { zh: "護盛修第捨，瓊仰視堂，歎曰：「酣酒嗜音，峻宇雕牆，有一於此，未或不亡。", literal: "Hu was lavishly repairing his residence. Qiong looked up at the hall and sighed: \"Deep drinking and love of music, lofty halls and carved walls—if any one of these is present, none has failed to perish.\"", idiomatic: "Hu was lavishly rebuilding his residence. Qiong looked up at the hall and sighed: \"Deep drink and love of music, lofty halls and carved walls—one of these has never failed to end a house.\"" },
  { zh: "」護不悅。", literal: "Hu was displeased.", idiomatic: "Hu was displeased." },
  { zh: "驃騎大將軍、開府儀同三司寇俊，贊之孫也，少有學行。", literal: "Grand General, Grand Master of Splendid Happiness Kou Jun was grandson of Kou Zan and from youth had learning and conduct.", idiomatic: "Grand general and grand master of splendid happiness Kou Jun was Kou Zan's grandson, learned and upright from youth." },
  { zh: "家人嘗賣物，多得絹五匹，俊於後知之，曰：「得財失行，吾所不取。", literal: "His household once sold goods and took five extra bolts of silk. When Jun learned of it afterward he said, \"To gain wealth and lose integrity—that I will not take.\"", idiomatic: "His household once sold goods and kept five extra bolts of silk. Learning of it later, Jun said, \"Wealth gained by losing integrity—I will not keep.\"" },
  { zh: "」訪主還之。", literal: "He sought the buyer and returned them.", idiomatic: "He found the buyer and returned them." },
  { zh: "敦睦宗族，與同豐約，教訓子孫，必先禮義。", literal: "He was kind to his clan, shared abundance and want with them, and in teaching his descendants always put ritual and right first.", idiomatic: "He cherished his clan, shared feast and famine, and taught his sons ritual before all else." },
  { zh: "自大統中，稱老疾，不朝謁；", literal: "From the Great Unity period onward he claimed age and illness and did not attend court;", idiomatic: "From the Great Unity period he pleaded age and illness and stayed from court;" },
  { zh: "世宗虛心欲見之，俊不得已入見。", literal: "Shizong wished sincerely to see him, and Jun had no choice but to enter audience.", idiomatic: "Shizong wished to see him; Jun could not refuse audience." },
  { zh: "王引之同席而坐，問以魏朝舊事；", literal: "The king drew him to sit on the same mat and asked about old affairs of the Wei court;", idiomatic: "The king drew him to the same mat and asked of Wei days;" },
  { zh: "載以御輿，令於王前乘之以出，顧謂左右曰：「如此之事，唯積善者可以致之。", literal: "he had him borne on the imperial litter and ordered him to ride out before the king, then turned to those about him and said, \"Such a thing only one who has piled up goodness can attain.\"", idiomatic: "he had him borne on the imperial litter and ride out before the throne, then said to his attendants, \"Only piled-up goodness wins such a thing.\"" },
  { zh: "周文育之討余孝勱也，帝令南豫州刺史侯安都繼之。", literal: "When Zhou Wenyu campaigned against Yu Xiaomo, the emperor ordered Inspector of South Yuzhou Hou An'du to follow up.", idiomatic: "When Zhou Wenyu campaigned against Yu Xiaomo, the emperor ordered south Yuzhou inspector Hou An'du to follow." },
  { zh: "文育死，安都還，遇王琳將周靈、周協南歸，與戰，擒之。", literal: "After Wenyu died, An'du returned and met Wang Lin's generals Zhou Ling and Zhou Xie returning south. He fought and captured them.", idiomatic: "After Wenyu's death An'du returned, met Wang Lin's generals Zhou Ling and Zhou Xie heading south, fought, and took them." },
  { zh: "孝勱弟孝猷帥所部四千家詣安都降。", literal: "Xiaomo's younger brother Xiaoyou led his four thousand households to surrender to An'du.", idiomatic: "Xiaomo's brother Xiaoyou led four thousand households to surrender to An'du." },
  { zh: "安都進軍至左裡，擊曹慶、常眾愛，破之。", literal: "An'du advanced to Zuoli, struck Cao Qing and Chang Zhong'ai, and defeated them.", idiomatic: "An'du advanced to Zuoli, struck Cao Qing and Chang Zhong'ai, and broke them." },
  { zh: "眾愛奔廬山，庚寅，廬山民斬之，傳首。", literal: "Zhong'ai fled to Lushan. On gengyin the people of Lushan beheaded him and sent the head.", idiomatic: "Zhong'ai fled to Lushan. On gengyin the mountain people beheaded him and sent the head." },
  { zh: "詔臨川王蒨於南皖口置城，使東徐州刺史吳興錢道戢守之。", literal: "An edict ordered Prince Qian of Linchuan to build a city at Nanwankou and made Qian Daoyi of Wuxing, Inspector of East Xuzhou, defend it.", idiomatic: "An edict ordered Prince Qian of Linchuan to fortify Nanwankou and made Qian Daoyi of Wuxing, east Xuzhou inspector, hold it." },
  { zh: "丁酉，上不豫，丙午，殂。", literal: "On dingyou the emperor fell ill; on bingwu he died.", idiomatic: "On dingyou the emperor fell ill; on bingwu he died." },
  { zh: "上臨戎制勝，英謀獨運，而為政務崇寬簡，非軍旅急務，不輕調發。", literal: "In battle he seized victory; his stratagems he bore alone—yet in government he prized lenience and simplicity. Unless the army was urgent, he would not lightly levy.", idiomatic: "In war he read the field and won; his designs were his alone—yet he ruled with lenience and restraint, never levying unless the host demanded it." },
  { zh: "性儉素，常膳不過數品，私宴用瓦器、蚌盤，殽核充事而已；", literal: "His nature was frugal and plain. Regular meals were never more than a few dishes; private feasts used earthenware and clam shells, with food enough and no more;", idiomatic: "He lived plainly: daily meals were few dishes; private feasts used pottery and clam platters, enough and no more;" },
  { zh: "後宮無金翠之飾，不設女樂。", literal: "the inner palace had no gold or kingfisher adornment and kept no female musicians.", idiomatic: "the inner quarters wore no gold or kingfisher, and kept no women's music." },
  { zh: "時皇子昌在長安，內無嫡嗣，外有強敵，宿將皆將兵在外，朝無重臣，唯中領軍杜稜典宿衛兵在建康。", literal: "The prince Chang was then in Chang'an. Within there was no legitimate heir; without, strong enemies pressed. Veteran generals all held troops abroad; the court had no weighty minister—only Central Guard Commander Du Ling commanded the garrison at Jiankang.", idiomatic: "Prince Chang was in Chang'an. Within, no legitimate heir; without, enemies closed in. Veterans held armies abroad; the court had no pillar—only central guard commander Du Ling held Jiankang's garrison." },
  { zh: "章皇后召稜及中書侍郎蔡景歷入禁中定議，秘不發喪，急召臨川王蒨於南□宛。", literal: "Empress Zhang summoned Ling and Secretariat Gentleman Cai Jingli into the inner palace to settle policy, keeping the death secret and urgently summoning Prince Qian of Linchuan from Nan□wan.", idiomatic: "Empress Zhang called Ling and secretariat gentleman Cai Jingli within to decide, hid the death, and urgently summoned Prince Qian of Linchuan from Nan□wan." },
  { zh: "景歷親與宦者、宮人密營斂具。", literal: "Jingli himself, with eunuchs and palace women, secretly prepared the burial gear.", idiomatic: "Jingli himself, with eunuchs and palace women, secretly prepared the burial gear." },
  { zh: "時天暑，須治梓宮，恐斤斧之聲聞於外，乃以蠟為秘器。", literal: "It was hot; they needed to work the outer coffin and feared axe-strokes would be heard outside, so they made a secret vessel of wax.", idiomatic: "The heat required a coffin, but axe-strokes might be heard—so they fashioned a secret shell of wax." },
  { zh: "文書詔敕，依舊宣行。", literal: "Documents, edicts, and orders continued to be promulgated as before.", idiomatic: "Edicts and orders still went out as before." },
  { zh: "侯安都軍還，適至南皖，與臨川王俱還朝。", literal: "Hou An'du's army returned and happened to reach South Wan, returning to court together with the Prince of Linchuan.", idiomatic: "Hou An'du's army returned, reached South Wan, and entered the capital with the prince of Linchuan." },
  { zh: "甲寅，王至建康，入居中書省，安都與群臣定議，奉王嗣位，王謙讓不敢當。", literal: "On jiayin the prince reached Jiankang, entered the Secretariat, and An'du with the ministers settled on enthroning him. The prince demurred and dared not accept.", idiomatic: "On jiayin the prince reached Jiankang and took seat in the Secretariat. An'du and the ministers resolved to enthrone him; the prince demurred." },
  { zh: "皇后以昌故，未肯下令，群臣猶豫不能決。", literal: "Because of Chang, the empress would not issue the order; the ministers hesitated and could not decide.", idiomatic: "For Chang's sake the empress would not decree; the court hung undecided." },
  { zh: "安都曰：「今四方未定，何暇及遠！", literal: "An'du said, \"The four quarters are not settled—what leisure for the distant!\"", idiomatic: "An'du said, \"The realm is unsettled—who has leisure for the far heir!\"" },
  { zh: "臨川王有大功於天下，須共立之。", literal: "\"The Prince of Linchuan has great merit under heaven; we must establish him together.", idiomatic: "\"The prince of Linchuan has merit under heaven; we must raise him together." },
  { zh: "今日之事，後應者斬！", literal: "\"In today's matter, whoever answers late—behead!\"", idiomatic: "\"Whoever hesitates today—dies!\"" },
  { zh: "」即按劍上殿，白皇后出璽，又手解蒨發，推就喪次，遷殯大行於太極西階。", literal: "He drew his sword, went up the hall, told the empress to produce the seal, with his own hand loosened Qian's hair, pushed him to the mourning place, and moved the late emperor's coffin to the west steps of Taiji.", idiomatic: "He drew his sword, mounted the hall, demanded the seal, loosed Qian's hair with his own hand, thrust him to the bier, and moved the late emperor's coffin to the west steps of Taiji." },
  { zh: "皇后乃下令，以茜纂承大統。", literal: "The empress then issued the order that Qian should succeed to the great succession.", idiomatic: "The empress then decreed that Qian should succeed." },
  { zh: "是日，即皇帝位，大赦。", literal: "That day he took the throne and proclaimed a general amnesty.", idiomatic: "That day he took the throne and proclaimed amnesty." },
  { zh: "秋，七月，丙辰，尊皇后為皇太后。", literal: "In autumn, the seventh month, on bingchen, the empress was honored as empress dowager.", idiomatic: "Autumn, seventh month, on bingchen, the empress was honored as empress dowager." },
  { zh: "辛酉，以侯瑱為太尉，侯安都為司空。", literal: "On xinyou, Hou Tian was made Grand Commandant and Hou An'du Minister of Works.", idiomatic: "On xinyou, Hou Tian was made grand commandant and Hou An'du minister of works." },
  { zh: "齊顯祖將如晉陽，乃盡誅諸元，或祖父為王，或身嘗貴顯，皆斬於東市，其嬰兒投於空中，承之以槊。", literal: "As Emperor Xianzu was about to go to Jinyang, he slaughtered all the Yuans. Some had grandfathers who had been kings, some had themselves once been eminent—all were beheaded at the Eastern Market. Infants were tossed into the air and caught on spears.", idiomatic: "As Emperor Xianzu prepared for Jinyang, he exterminated the Yuans. Some had royal grandfathers, some had once held high rank—all died at the Eastern Market. Infants were thrown skyward and caught on spears." },
  { zh: "前後死者凡七百二十一人，悉棄屍漳水，剖魚者往往得人爪甲，鄴下為之久不食魚。", literal: "In all, seven hundred twenty-one died before and after; the bodies were cast into the Zhang River. When fish were gutted, human nails often appeared; for a long time Ye would not eat fish.", idiomatic: "Seven hundred twenty-one perished; corpses filled the Zhang. Gutting fish, people often found fingernails—for years Ye would not eat fish." },
  { zh: "使元黃頭與諸囚自金鳳台各乘紙鴟以飛，黃頭獨能至紫陌乃墮，仍付御史中丞畢義雲餓殺之。", literal: "He made Yuan Huangtou and other prisoners ride paper kites from the Golden Phoenix Terrace; Huangtou alone reached Zimo before falling, and was then handed to Imperial Censor Bil Yiyun to starve.", idiomatic: "He made Yuan Huangtou and other prisoners fly paper kites from Golden Phoenix Terrace; only Huangtou reached Zimo before falling—then Bil Yiyun starved him." },
  { zh: "唯開府儀同三司元蠻、祠部郎中元文遙等數家獲免。", literal: "Only Grand Master of Splendid Happiness Yuan Man, Secretariat Gentleman Yuan Wenyuan, and a few other households were spared.", idiomatic: "Only grand master Yuan Man, gentleman Yuan Wenyuan, and a few households were spared." },
  { zh: "蠻，繼之子，常山王演之妃父；", literal: "Man was son of Ji and father-in-law to Prince Yan of Changshan;", idiomatic: "Man was Ji's son and Prince Yan of Changshan's father-in-law;" },
  { zh: "文遙，遵之五世孫也。", literal: "Wenyuan was fifth-generation descendant of Zun.", idiomatic: "Wenyuan was Zun's fifth-generation descendant." },
  { zh: "定襄令元景安，虔之玄孫也，欲請改姓高氏，其從兄景皓曰：「安有棄其本宗而從人之姓者乎！", literal: "Yuan Jing'an, magistrate of Dingxiang, great-great-grandson of Qian, wished to petition to change his surname to Gao. His elder cousin Jinghao said, \"How can one abandon one's own clan and take another's surname!", idiomatic: "Magistrate Yuan Jing'an of Dingxiang, Qian's great-great-grandson, sought to take the surname Gao. His cousin Jinghao said, \"Who abandons his own house for another man's name!" },
  { zh: "丈夫寧可玉碎，何能瓦全！", literal: "\"A man would rather be jade shattered than tile whole!\"", idiomatic: "\"Better jade shattered than tile whole!\"" },
  { zh: "」景安以其言白帝，帝收景皓，誅之，賜景安姓高氏。", literal: "Jing'an reported his words to the emperor. The emperor seized Jinghao and executed him, granting Jing'an the surname Gao.", idiomatic: "Jing'an informed on him. The emperor seized Jinghao and killed him, granting Jing'an the surname Gao." },
  { zh: "八月，甲申，葬武皇帝於萬安陵，廟號高祖。", literal: "In the eighth month, on jiashen, Emperor Wu was buried at Wan'an Mausoleum; temple title Gaozu.", idiomatic: "Eighth month, on jiashen, Emperor Wu was buried at Wan'an; temple name Gaozu." },
  { zh: "戊戌，齊封皇子紹義為廣陽王；", literal: "On wuxu, Qi enfeoffed Prince Shao'yi of Guangyang;", idiomatic: "On wuxu, Qi made Prince Shao'yi of Guangyang;" },
  { zh: "以尚書右僕射河間王孝琬為左僕射，都官尚書崔昂為右僕射。", literal: "made Right Vice Director Prince Xiaowan of Hejian Left Vice Director and Minister of Justice Cui Ang Right Vice Director.", idiomatic: "made right vice director Prince Xiaowan of Hejian left vice director, and minister of justice Cui Ang right vice director." },
  { zh: "周御正中大夫崔猷建議，以為：「聖人沿革，因時制宜。", literal: "Zhou's Director of the Imperial Secretariat Cui You submitted that \"sages change institutions to suit the times.", idiomatic: "Northern Zhou's director of the imperial secretariat Cui You argued: \"Sages revise institutions as times require." },
  { zh: "今天子稱王，不足以威天下，請遵秦、漢舊制稱皇帝，建年號。", literal: "\"Today the Son of Heaven is styled king—this is not enough to awe the world. I ask that the Qin and Han precedent of emperor be followed and an era name established.\"", idiomatic: "\"The Son of Heaven is called king—that cannot awe the world. Follow Qin and Han: take the title emperor and establish an era.\"" },
  { zh: "」己亥，周王始稱皇帝，追遵文王曰文皇帝，改元武成。", literal: "On jihai the Zhou king first styled himself emperor, posthumously honored Duke Wen as Emperor Wen, and changed the era to Wucheng.", idiomatic: "On jihai the Zhou ruler took the title emperor, honored Duke Wen as Emperor Wen, and changed the era to Wucheng." },
  { zh: "癸卯，齊詔：「民間或有父祖冒姓元氏，或假托攜養者，不問世數遠近，悉聽改復本姓。", literal: "On guimao, Qi decreed: \"Among the people, if fathers or grandfathers falsely took the surname Yuan, or falsely claimed adoption, regardless how many generations distant, all may restore their original surnames.\"", idiomatic: "On guimao Qi decreed: \"If fathers or grandfathers falsely bore the surname Yuan or falsely claimed adoption, all may restore their original surnames, however many generations have passed.\"" },
  { zh: "初，高祖追謚兄道譚為始興昭烈王，以其次子頊襲封。", literal: "Earlier, Gaozu had posthumously honored his brother Dao Tan as Prince Zhaolie of Shixing and had his second son Xu inherit the fief.", idiomatic: "Earlier Gaozu had posthumously honored his brother Dao Tan as Prince Zhaolie of Shixing; his second son Xu inherited the fief." },
  { zh: "及世祖即位，頊在長安未還，上以本宗乏享，戊戌，詔徙封頊為安成王，皇子伯茂為始興王。", literal: "When Shizu ascended, Xu was still in Chang'an and had not returned. The emperor, because the main line lacked sacrifice, on wuxu ordered Xu moved to Prince of Ancheng and the prince Boma made Prince of Shixing.", idiomatic: "When Shizu ascended, Xu remained in Chang'an. Because the main line lacked an heir at the altar, on wuxu Xu was made prince of Ancheng and Prince Boma prince of Shixing." },
  { zh: "初，周太祖平蜀，以其形勝之地，不欲使宿將居之，問諸子：「誰可往者？", literal: "Earlier, when Zhou's founding emperor pacified Shu, because the land was strategically strong he did not wish old generals to hold it. He asked his sons, \"Who can go?\"", idiomatic: "When the founding emperor pacified Shu, he would not trust old generals in that stronghold and asked his sons, \"Who can go?\"" },
  { zh: "」皆不對。", literal: "None answered.", idiomatic: "None answered." },
  { zh: "少子安成公憲請行，太祖以其幼，不許。", literal: "The youngest son, Duke Xian of Ancheng, asked to go; the founding emperor thought him young and did not permit.", idiomatic: "The youngest, Duke Xian of Ancheng, volunteered; the founder thought him too young and refused." },
  { zh: "壬子，周人以憲為益州總管，時年十六，善於撫綏，留心政術，蜀人悅之。", literal: "On renzi, Zhou made Xian Inspector-General of Yizhou. He was sixteen years old, skilled in comfort and control, attentive to government—Shu people were pleased.", idiomatic: "On renzi Northern Zhou made Xian inspector-general of Yizhou at sixteen. He governed with care; the Shu were pleased." },
  { zh: "九月，乙卯，以大將軍天水公廣為梁州總管。", literal: "In the ninth month, on yimao, Grand General Duke Guang of Tianshui was made Inspector-General of Liangzhou.", idiomatic: "Ninth month, on yimao, grand general Duke Guang of Tianshui was made inspector-general of Liangzhou." },
  { zh: "廣，導之子也。", literal: "Guang was son of Dao.", idiomatic: "Guang was Dao's son." },
  { zh: "辛酉，立皇子伯宗為太子。", literal: "On xinyou, Prince Zongbo was established as heir apparent.", idiomatic: "On xinyou, Prince Zongbo was made heir apparent." },
  { zh: "己巳，齊齊如晉陽。", literal: "On jisi, Qi Qi went to Jinyang.", idiomatic: "On jisi, Qi Qi went to Jinyang." },
  { zh: "辛未，周主封其弟輔成公邕為魯公，安成公憲為齊公，純為陳公，盛為越公，達為代公，通為冀公，逌為滕公。", literal: "On xinwei, the Zhou ruler enfeoffed his younger brother Duke Yong of Fucheng as Duke of Lu, Duke Xian of Ancheng as Duke of Qi, Chun as Duke of Chen, Sheng as Duke of Yue, Da as Duke of Dai, Tong as Duke of Ji, and You as Duke of Teng.", idiomatic: "On xinwei the Zhou ruler enfeoffed Duke Yong of Fucheng as duke of Lu, Duke Xian of Ancheng as duke of Qi, Chun as duke of Chen, Sheng as duke of Yue, Da as duke of Dai, Tong as duke of Ji, and You as duke of Teng." },
  { zh: "乙亥，立太子母吳興沈妃為皇后。", literal: "On yihai, the heir's mother, Lady Shen of Wuxing, was established as empress.", idiomatic: "On yihai the heir's mother, Lady Shen of Wuxing, was made empress." },
  { zh: "周少保懷寧莊公蔡祐卒。", literal: "Young Tutor Duke Zhuang of Huaining, Cai You, died.", idiomatic: "Young tutor Duke Zhuang of Huaining, Cai You, died." },
  { zh: "齊顯祖嗜酒成疾，不復能食，自知不能久，謂李後曰：「人生必有死，何足致惜！", literal: "Emperor Xianzu's drinking had become disease; he could no longer eat and knew he would not last. He told Empress Li, \"Life must end—why regret it!\"", idiomatic: "Emperor Xianzu's drinking had ruined him; he could no longer eat and knew the end was near. He told Empress Li, \"All men die—why grieve!\"" },
  { zh: "但憐正道尚幼，人將奪之耳！", literal: "He also said, \"But I pity that Zhengdao is still young—men will seize him!\"", idiomatic: "He also said, \"But Zhengdao is young—others will tear the throne from him!\"" },
  { zh: "」又謂常山王演曰：「奪則任汝，慎勿殺也！", literal: "He also told Prince Yan of Changshan, \"If they seize it, it is yours—take care not to kill!\"", idiomatic: "He told Prince Yan of Changshan, \"If they seize it, it is yours—do not kill!\"" },
  { zh: "」尚書令開封王楊愔、領軍大將軍平秦王歸彥、侍中廣漢燕子獻、黃門侍郎鄭頤皆受遺詔輔政。", literal: "Minister of Education Yang Yin of Kaifeng, Grand General Prince Guiping Guiyan, Palace Attendant Yanzi Xian of Guanghan, and Gentleman of the Yellow Gate Zheng Yi all received testamentary charge to assist.", idiomatic: "Minister of education Yang Yin of Kaifeng, grand general Prince Guiping Guiyan, palace attendant Yanzi Xian of Guanghan, and yellow gate gentleman Zheng Yi were charged to assist." },
  { zh: "冬，十月，甲午，殂。", literal: "In winter, the tenth month, on jiawu, he died.", idiomatic: "Winter, tenth month, on jiawu, he died." },
  { zh: "癸卯，發喪，群臣號哭，無下泣者，唯楊愔涕泗嗚咽。", literal: "On guimao mourning was proclaimed. The ministers wailed; none wept below—only Yang Yin sobbed with tears and choking.", idiomatic: "On guimao mourning was proclaimed. Ministers cried aloud; none wept from the heart—only Yang Yin sobbed." },
  { zh: "太子殷即位，大赦。", literal: "The crown prince Yin succeeded and proclaimed a general amnesty.", idiomatic: "Crown prince Yin succeeded and proclaimed amnesty." },
  { zh: "庚戌，尊皇太后為太皇太后，皇后為皇太后；", literal: "On gengxu the empress dowager was honored as grand empress dowager and the empress as empress dowager;", idiomatic: "On gengxu the empress dowager became grand empress dowager and the empress empress dowager;" },
  { zh: "詔諸土木金鐵雜匠一切停罷。", literal: "an edict halted all craftsmen in earth, wood, metal, and iron.", idiomatic: "an edict halted all craftsmen in earth, wood, metal, and iron." },
  { zh: "王琳聞高祖殂，乃以少府卿吳郡孫瑒為郢州刺史，總留任，奉梁永嘉王莊出屯濡須口，齊揚州道行台慕容儼帥眾臨江，為之聲援。", literal: "Wang Lin, hearing of Gaozu's death, made Secretariat Director Sun Yong of Wu prefect of Yingzhou to oversee the rear, escorted Liang's Prince Zhuang of Yongjia to camp at Ruxukou, and Qi's frontier commissioner Murong Yan led troops to the river as support.", idiomatic: "Wang Lin, hearing Gaozu had died, made secretariat director Sun Yong of Wu prefect of Yingzhou to hold the rear, marched Liang's Prince Zhuang of Yongjia to Ruxukou, and Qi's frontier commissioner Murong Yan brought troops to the river in support." },
  { zh: "十一月，乙卯，琳寇大雷，詔侯瑱、侯安都及儀同徐度將兵御之。", literal: "In the eleventh month, on yimao, Lin raided Dalei. An edict ordered Hou Tian, Hou An'du, and Grand Master of Splendid Happiness Xu Du to resist.", idiomatic: "Eleventh month, on yimao, Lin raided Dalei. Hou Tian, Hou An'du, and grand master Xu Du were ordered to meet him." },
  { zh: "安州刺史吳明徹夜襲湓城，琳遣巴陵太守任忠擊明徹，大破之，明徹僅以身免。", literal: "Inspector of Anzhou Wu Mingche raided Pencheng by night. Lin sent Administrator Ren Zhong of Baling to strike Mingche and routed him; Mingche barely escaped with his life.", idiomatic: "Anzhou inspector Wu Mingche raided Pencheng by night. Lin sent Baling administrator Ren Zhong against him, broke him utterly; Mingche fled alone." },
  { zh: "琳因引兵東下。", literal: "Lin then led his army east.", idiomatic: "Lin then marched east." },
  { zh: "齊以右丞相斛律金為左丞相，常山王演為太傅，長廣王湛為太尉，段韶為司徒，平原王淹為司空，高陽王湜為尚書左僕射，河間王孝琬為司州牧，侍中燕子獻為右僕射。", literal: "Qi made Right Chancellor Hu Lv Jin Left Chancellor, Prince Yan of Changshan Grand Tutor, Prince Guang of Changgang Grand Commandant, Duan Shao Minister of Education, Prince Yan of Pingyuan Minister of Works, Prince Shi of Gaoyang Left Vice Director, Prince Xiaowan of Hejian Governor of Sizhou, and Palace Attendant Yanzi Xian Right Vice Director.", idiomatic: "Qi made right chancellor Hu Lv Jin left chancellor, Prince Yan of Changshan grand tutor, Prince Guang of Changgang grand commandant, Duan Shao minister of education, Prince Yan of Pingyuan minister of works, Prince Shi of Gaoyang left vice director, Prince Xiaowan of Hejian governor of Sizhou, and palace attendant Yanzi Xian right vice director." },
  { zh: "辛未，齊顯祖之喪至鄴。", literal: "On xinwei, Emperor Xianzu's coffin reached Ye.", idiomatic: "On xinwei Emperor Xianzu's coffin reached Ye." },
  { zh: "十二月，戊戌，齊徙上黨王紹仁為漁陽王，廣陽王紹義為范陽王，長樂王紹廣為隴西王。", literal: "In the twelfth month, on wuxu, Qi moved Prince Shaoren of Shangdang to Prince of Yuyang, Prince Shao'yi of Guangyang to Prince of Fanyang, and Prince Shaoguang of Changle to Prince of Longxi.", idiomatic: "Twelfth month, on wuxu, Qi moved Prince Shaoren of Shangdang to Yuyang, Prince Shao'yi of Guangyang to Fanyang, and Prince Shaoguang of Changle to Longxi." },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
